    ]
  };

  /* ------------------------------------------------------------------------
   * UTILITAS
   * ------------------------------------------------------------------------ */
  var TZ = 'Asia/Jakarta';
  var SESSION_KEY = 'km_session_v5';
  var TIMER_KEY = 'km_timer_v5';

  function $(sel, root) { return (root || document).querySelector(sel); }
  function $$(sel, root) { return Array.prototype.slice.call((root || document).querySelectorAll(sel)); }
  function esc(v) {
    return String(v === undefined || v === null ? '' : v)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
  }
  function num(v) { var n = Number(v); return isFinite(n) ? n : 0; }
  function fmt(n) { return num(n).toLocaleString('id-ID'); }
  function pct(a, b) { return b ? Math.min(100, Math.round((a / b) * 100)) : 0; }
  function initials(name) {
    var p = String(name || 'P').trim().split(/\s+/);
    return ((p[0] || 'P').charAt(0) + (p.length > 1 ? p[p.length - 1].charAt(0) : '')).toUpperCase();
  }
  var GRADS = ['#6938EF', '#2BA69E', '#F47292', '#F59E0B', '#4A3267'];
  function colorFor(str) {
    var h = 0; str = String(str || '');
    for (var i = 0; i < str.length; i++) h = (h * 31 + str.charCodeAt(i)) >>> 0;
    return GRADS[h % GRADS.length];
  }
  function avatarHTML(user, size) {
    var cls = 'avatar ' + (size || '');
    if (user && user.avatarURL) return '<span class="' + cls + '"><img src="' + esc(user.avatarURL) + '" alt="" loading="lazy" referrerpolicy="no-referrer"></span>';
    var name = user && (user.name || user.userName) || 'P';
    return '<span class="' + cls + '" style="background:' + colorFor(name) + '" aria-hidden="true">' + esc(initials(name)) + '</span>';
  }
  function dayKey(d) { return (d || new Date()).toLocaleDateString('en-CA', { timeZone: TZ }); }
  function todayKey() { return dayKey(new Date()); }
  function addDays(key, n) {
    var t = Date.parse(String(key).slice(0, 10) + 'T00:00:00Z') + n * 864e5;
    return new Date(t).toISOString().slice(0, 10);
  }
  function fmtDate(s, withYear) {
    if (!s) return '—';
    var d = /^\d{4}-\d{2}-\d{2}$/.test(String(s)) ? new Date(s + 'T00:00:00+07:00') : new Date(s);
    if (isNaN(d.getTime())) return String(s);
    return d.toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: withYear === false ? undefined : 'numeric', timeZone: TZ });
  }
  function fmtTime(s) {
    if (!s) return '';
    var d = new Date(s);
    if (isNaN(d.getTime())) return String(s).slice(0, 5);
    return d.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit', timeZone: TZ });
  }
  function fmtDur(min) {
    min = Math.round(num(min));
    if (min < 60) return min + ' mnt';
    var h = Math.floor(min / 60), m = min % 60;
    return h + ' j' + (m ? ' ' + m + ' mnt' : '');
  }
  function timeHM(d) { return d.toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit', hour12: false, timeZone: TZ }).replace('.', ':'); }
  function debounce(fn, ms) { var t; return function () { var a = arguments, c = this; clearTimeout(t); t = setTimeout(function () { fn.apply(c, a); }, ms); }; }
  function readFileAsDataURL(file) {
    return new Promise(function (resolve, reject) {
      var r = new FileReader();
      r.onload = function () { resolve(r.result); };
      r.onerror = function () { reject(new Error('Berkas tidak dapat dibaca.')); };
      r.readAsDataURL(file);
    });
  }

  /* Kompresi sampul agar payload kecil (maks 1200px, JPEG). */
  function compressCover(file) {
    return new Promise(function (resolve, reject) {
      if (!/^image\/(jpeg|png|webp)$/.test(file.type)) return reject(new Error('Format sampul harus JPG, PNG, atau WEBP.'));
      if (file.size > 8 * 1024 * 1024) return reject(new Error('Ukuran berkas terlalu besar (maks 8 MB sebelum kompresi).'));
      var url = URL.createObjectURL(file);
      var img = new Image();
      img.onload = function () {
        var max = 1200, w = img.naturalWidth, h = img.naturalHeight;
        var s = Math.min(1, max / Math.max(w, h));
        var c = document.createElement('canvas');
        c.width = Math.round(w * s); c.height = Math.round(h * s);
        var ctx = c.getContext('2d');
        ctx.fillStyle = '#FFFFFF'; ctx.fillRect(0, 0, c.width, c.height);
        ctx.drawImage(img, 0, 0, c.width, c.height);
        var dataUrl = c.toDataURL('image/jpeg', 0.88);
        URL.revokeObjectURL(url);
        resolve({ base64: dataUrl.split(',')[1], mimeType: 'image/jpeg', fileName: (file.name || 'sampul').replace(/\.[a-z0-9]+$/i, '') + '.jpg', previewUrl: dataUrl });
      };
      img.onerror = function () { URL.revokeObjectURL(url); reject(new Error('Gambar tidak dapat diproses.')); };
      img.src = url;
    });
  }

