    sparkle: '<path d="M12 3v3M12 18v3M3 12h3M18 12h3M5.6 5.6l2.1 2.1M16.3 16.3l2.1 2.1M5.6 18.4l2.1-2.1M16.3 7.7l2.1-2.1"/>',
    target: '<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',
    download: '<path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4M7 10l5 5 5-5M12 15V3"/>',
    refresh: '<path d="M21 12a9 9 0 1 1-3-6.7L21 8"/><path d="M21 3v5h-5"/>',
    globe: '<circle cx="12" cy="12" r="10"/><path d="M2 12h20M12 2a15 15 0 0 1 0 20M12 2a15 15 0 0 0 0 20"/>',
    layers: '<path d="m12 2 10 5-10 5L2 7z"/><path d="m2 17 10 5 10-5M2 12l10 5 10-5"/>',
    award: '<circle cx="12" cy="8" r="7"/><path d="m8.2 14.6-1.2 7.4 5-2.7 5 2.7-1.2-7.4"/>',
    flame: '<path d="M8.5 14.5A2.5 2.5 0 0 0 11 12c0-1.38-.5-2-1-3-1.07-2.14-.22-4.05 2-6 .5 2.5 2 4.9 4 6.5 2 1.6 3 3.5 3 5.5a7 7 0 1 1-14 0c0-1.15.43-2.29 1-3a2.5 2.5 0 0 0 2.5 2.5z"/>',
    notebook: '<path d="M4 4h12a4 4 0 0 1 4 4v12H8a4 4 0 0 1-4-4z"/><path d="M8 4v16M12 9h4M12 13h4"/>',
    chart: '<path d="M3 3v18h18"/><path d="M7 15v3M12 10v8M17 6v12"/>',
    camera: '<path d="M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z"/><circle cx="12" cy="13" r="4"/>',
    eye: '<path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/>',
    key: '<circle cx="7.5" cy="15.5" r="5.5"/><path d="m21 2-9.6 9.6M15.5 7.5l3 3L22 7l-3-3"/>',
    info: '<circle cx="12" cy="12" r="10"/><path d="M12 16v-4M12 8h.01"/>',
    alert: '<path d="M10.3 3.9 1.8 18a2 2 0 0 0 1.7 3h17a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0z"/><path d="M12 9v4M12 17h.01"/>',
    more: '<circle cx="5" cy="12" r="1.5"/><circle cx="12" cy="12" r="1.5"/><circle cx="19" cy="12" r="1.5"/>',
    bookmark: '<path d="M19 21l-7-5-7 5V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2z"/>',
    'user-plus': '<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M19 8v6M22 11h-6"/>',
    'user-check': '<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="m16 11 2 2 4-4"/>',
    'chevron-up': '<path d="m18 15-6-6-6 6"/>',
    'list-ordered': '<path d="M10 6h11M10 12h11M10 18h11"/><path d="M4 6h1v4M4 10h2M4 18h2l-2 2h2"/>',
    grip: '<circle cx="9" cy="6" r="1"/><circle cx="15" cy="6" r="1"/><circle cx="9" cy="12" r="1"/><circle cx="15" cy="12" r="1"/><circle cx="9" cy="18" r="1"/><circle cx="15" cy="18" r="1"/>'
  };
  ICONS.timer = ICONS.clock;
  ICONS.cover = ICONS.image;
  function ic(name, cls) {
    var p = ICONS[name] || ICONS.info;
    return '<svg class="ic' + (cls ? ' ' + cls : '') + '" viewBox="0 0 24 24" aria-hidden="true" focusable="false">' + p + '</svg>';
  }
  function hydrateIcons(root) {
    $$('[data-ic]', root).forEach(function (n) { n.innerHTML = ic(n.getAttribute('data-ic')); });
    $$('[data-ic-wrap]', root).forEach(function (n) { n.innerHTML = ic(n.getAttribute('data-ic-wrap')); });
  }

  /* ------------------------------------------------------------------------
   * STATE
   * ------------------------------------------------------------------------ */
  var S = {
    token: '', user: null, dash: null, adminBackup: null,
    route: { page: '', id: '' }, filter: { status: 'all', q: '' },
    explore: { tab: 'orang', q: '', topic: '' },
    kelas: { q: '' }, lbClass: '', lbDays: 30,
    charts: [], timer: null, timerTick: null, appBuilt: false, landingBuilt: false,
    modals: [], cache: {}
  };

  /* ------------------------------------------------------------------------
   * API
   * ------------------------------------------------------------------------ */
  var AUTH_CODES = ['UNAUTHENTICATED', 'SESSION_EXPIRED', 'SESSION_INVALID'];
  function apiReady() { return CFG.API_URL.indexOf('REPLACE_WITH') === -1; }

  function api(action, data) {
    if (!apiReady()) return Promise.reject(new Error('URL API belum diatur. Edit CFG.API_URL pada tema.'));
    var body = JSON.stringify({ action: action, token: S.token || '', data: data || {} });
    return fetch(CFG.API_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'text/plain;charset=utf-8' },
      body: body,
      redirect: 'follow'
    }).then(function (r) { return r.text(); }).then(function (txt) {
      var res;
      try { res = JSON.parse(txt); } catch (e) { throw new Error('Respons server tidak valid. Coba lagi.'); }
      if (!res.success) {
        var err = new Error(res.message || 'Terjadi kesalahan.');
        err.code = res.code || '';
        if (AUTH_CODES.indexOf(err.code) >= 0 && S.token && action !== 'login') expireSession(err.message);
        throw err;
      }
      var d = res.data || {};
      if (res.message) d.__m = res.message;
      return d;
    });
  }
  function apiGet(params) {
    if (!apiReady()) return Promise.reject(new Error('URL API belum diatur.'));
    var q = Object.keys(params).map(function (k) { return encodeURIComponent(k) + '=' + encodeURIComponent(params[k]); }).join('&');
    return fetch(CFG.API_URL + '?' + q, { redirect: 'follow' }).then(function (r) { return r.json(); }).then(function (res) {
      if (!res.success) throw new Error(res.message || 'Gagal memuat data.');
      return res.data || {};
    });
  }

  function saveSession() {
    try { localStorage.setItem(SESSION_KEY, JSON.stringify({ token: S.token, user: S.user, admin: S.adminBackup })); } catch (e) { /* abaikan */ }
  }
  function loadSession() {
    try { return JSON.parse(localStorage.getItem(SESSION_KEY) || 'null'); } catch (e) { return null; }
  }
  function clearSession() {
    S.token = ''; S.user = null; S.dash = null; S.adminBackup = null;
    try { localStorage.removeItem(SESSION_KEY); } catch (e) { /* abaikan */ }
  }
  function isAdmin() { return !!(S.user && S.user.role === 'Admin'); }

  function expireSession(msg) {
    clearSession();
    toast(msg || 'Sesi Anda berakhir. Silakan masuk kembali.', 'info');
    stopCharts();
    showLanding();
    openLogin();
  }

  /* ------------------------------------------------------------------------
   * TOAST & MODAL
   * ------------------------------------------------------------------------ */
  function toast(msg, type) {
    var host = $('#toastHost');
    if (!host) return;
    var t = document.createElement('div');
    var kind = type || 'ok';
    t.className = 'toast ' + (kind === 'error' ? 'err' : kind);
    var icon = kind === 'error' ? 'alert' : (kind === 'info' ? 'info' : 'check');
    t.innerHTML = ic(icon) + '<div style="min-width:0">' + esc(msg) + '</div>';
    host.appendChild(t);
    setTimeout(function () { t.classList.add('out'); setTimeout(function () { t.remove(); }, 320); }, kind === 'error' ? 5200 : 3400);
  }
  function errMsg(e) { return (e && e.message) ? e.message : 'Terjadi kesalahan. Coba lagi.'; }

  /**
   * openModal({title, body, foot, size, dismissible, onOpen})
   * Mengembalikan objek {el, body, close}.
   */
  function openModal(o) {
    var prevFocus = document.activeElement;
    var back = document.createElement('div');
    back.className = 'modal-backdrop';
    var id = 'md' + Math.random().toString(36).slice(2, 8);
    back.innerHTML =
      '<div class="modal-card ' + (o.size || '') + '" role="dialog" aria-modal="true" aria-labelledby="' + id + '">' +
        '<div class="modal-head"><h2 id="' + id + '">' + esc(o.title || '') + '</h2>' +
        '<button type="button" class="btn btn-icon" data-md-close aria-label="Tutup">' + ic('x') + '</button></div>' +
        '<div class="modal-body">' + (o.body || '') + '</div>' +
        (o.foot ? '<div class="modal-foot">' + o.foot + '</div>' : '') +
      '</div>';
    $('#modalRoot').appendChild(back);
    hydrateIcons(back);
    var dismissible = o.dismissible !== false;
    var entry = { el: back, onClose: o.onClose, prevFocus: prevFocus, dismissible: dismissible };
    function close() {
      var i = S.modals.indexOf(entry);
      if (i >= 0) S.modals.splice(i, 1);
      back.remove();
      if (typeof entry.onClose === 'function') entry.onClose();
      if (prevFocus && prevFocus.focus && document.body.contains(prevFocus)) { try { prevFocus.focus(); } catch (e) { /* abaikan */ } }
    }
    entry.close = close;
    S.modals.push(entry);
    back.addEventListener('click', function (ev) {
      if (ev.target === back && dismissible) close();
      var btn = ev.target.closest && ev.target.closest('[data-md-close]');
      if (btn && back.contains(btn)) close();
    });
    var first = back.querySelector('.modal-body input, .modal-body select, .modal-body textarea, .modal-body button:not([data-md-close])');
    setTimeout(function () { if (first && !/Hapus|Keluar/i.test(first.textContent || '')) { try { first.focus({ preventScroll: true }); } catch (e) { /* abaikan */ } } }, 60);
    if (typeof o.onOpen === 'function') o.onOpen(back.querySelector('.modal-body'), back);
    return { el: back, body: back.querySelector('.modal-body'), close: close };
  }
  function closeTopModal() {
    var top = S.modals[S.modals.length - 1];
    if (top && top.dismissible) top.close();
  }
  function closeAllModals() { while (S.modals.length) S.modals[S.modals.length - 1].close(); }

  function confirmDialog(title, text, okLabel, danger) {
    return new Promise(function (resolve) {
      var done = false;
      var m = openModal({
        title: title,
        size: 'sm',
        body: '<p style="font-size:16px;color:var(--ink-2)">' + esc(text) + '</p>',
        foot: '<button type="button" class="btn btn-outline" data-md-close data-no>Batal</button>' +
              '<button type="button" class="btn ' + (danger ? 'btn-danger' : 'btn-primary') + '" data-yes>' + esc(okLabel || 'Ya, lanjutkan') + '</button>',
        onClose: function () { if (!done) { done = true; resolve(false); } }
      });
      m.el.querySelector('[data-yes]').addEventListener('click', function () {
        done = true; resolve(true); m.close();
      });
    });
  }

  function setBusy(btn, busy) {
    if (!btn) return;
    btn.classList.toggle('loading', !!busy);
    btn.disabled = !!busy;
    btn.setAttribute('aria-busy', busy ? 'true' : 'false');
  }

  /* ------------------------------------------------------------------------
   * CHART CLEANUP
   * ------------------------------------------------------------------------ */
  function stopCharts() {
    S.charts.forEach(function (c) { try { c.destroy(); } catch (e) { /* abaikan */ } });
    S.charts = [];
  }

  /* ------------------------------------------------------------------------
   * COVER VISUAL (Drive sampul atau gradien otomatis)
   * ------------------------------------------------------------------------ */
  function coverHTML(book, extra) {
    var title = book.title || 'Buku';
    var author = book.author || '';
    var color = colorFor(title);
    var gradCls = 'g' + (GRADS.indexOf(color) + 1);
    var tags = '';
    if (extra && extra.progress !== undefined) tags += '<span class="prog-tag">' + pct(book.currentPage, book.totalPages) + '%</span>';
    if (book.status === 'Finished') tags += '<span class="done-tag" title="Selesai">' + ic('check') + '</span>';
    var img = book.coverURL
      ? '<img src="' + esc(book.coverURL) + '" alt="Sampul ' + esc(title) + '" loading="lazy" referrerpolicy="no-referrer">'
      : '';
    return '<div class="cover ' + gradCls + ' ' + ((extra && extra.cls) || '') + '">' +
      '<div class="gen" aria-hidden="true"><b>' + esc(title) + '</b><small>' + esc(author) + '</small></div>' +
      img + tags + '</div>';
  }
  document.addEventListener('error', function (ev) {
    var t = ev.target;
    if (t && t.tagName === 'IMG' && t.closest && t.closest('.cover')) t.style.display = 'none';
    if (t && t.tagName === 'IMG' && t.closest && t.closest('.avatar')) t.parentNode.innerHTML = '';
  }, true);

  /* ------------------------------------------------------------------------
   * LANDING PAGE
   * ------------------------------------------------------------------------ */
  function buildLanding() {
    if (S.landingBuilt) return;
    S.landingBuilt = true;
    $('#testiGrid').innerHTML = CFG.TESTIMONIALS.map(function (t, i) {
      return '<figure class="tcard reveal" style="--d:' + (i * 100) + 'ms;margin:0">' +
        '<div class="stars" aria-label="Bintang lima">' + ic('star') + ic('star') + ic('star') + ic('star') + ic('star') + '</div>' +
        '<blockquote>“' + esc(t.text) + '”</blockquote>' +
        '<figcaption class="who"><span class="avatar" style="background:' + esc(t.color) + '">' + esc(t.initials) + '</span><div><b>' + esc(t.name) + '</b><span>' + esc(t.role) + '</span></div></figcaption></figure>';
    }).join('');
    $('#priceGrid').innerHTML = CFG.PRICING.map(function (p, i) {
      return '<div class="price reveal' + (p.featured ? ' featured' : '') + '" style="--d:' + (i * 100) + 'ms">' +
        (p.featured ? '<span class="badge">Paling populer</span>' : '') +
        '<h3>' + esc(p.name) + '</h3>' +
        '<div class="amount">' + esc(p.price) + ' <small>' + esc(p.unit) + '</small></div>' +
        '<ul>' + p.features.map(function (f) { return '<li>' + ic('check') + '<span>' + esc(f) + '</span></li>'; }).join('') + '</ul>' +
        '<button type="button" class="btn ' + (p.featured ? 'btn-primary' : 'btn-outline') + ' btn-block" data-open-register>' + esc(p.cta) + '</button></div>';
    }).join('');
    $('#faqList').innerHTML = CFG.FAQ.map(function (f, i) {
      return '<details class="reveal" style="--d:' + (i * 60) + 'ms"' + (i === 0 ? ' open' : '') + '><summary>' + esc(f.q) +
        '<span class="chev">' + ic('chevron-down', 'ic-sm') + '</span></summary><div class="ans">' + esc(f.a) + '</div></details>';
    }).join('');
    var mq = $('#marquee');
    if (mq && mq.children.length && !mq.dataset.dup) { mq.dataset.dup = '1'; mq.innerHTML += mq.innerHTML; }
    $('#yearNow').textContent = String(new Date().getFullYear());
    hydrateIcons($('#marketingView'));
    loadCatalog();
  }

  function loadCatalog() {
    var row = $('#catalogRow');
    if (!row) return;
    row.innerHTML = '<div class="bk skeleton" style="min-height:300px;flex:0 0 210px"></div><div class="bk skeleton" style="min-height:300px;flex:0 0 210px"></div><div class="bk skeleton" style="min-height:300px;flex:0 0 210px"></div>';
    apiGet({ action: 'publicCatalog' }).then(function (d) {
      var books = d.books || [];
      var st = d.stats || {};
      setCount('#statMembers', st.members);
      setCount('#statBooks', st.books);
      setCount('#statSessions', st.sessions);
      setCount('#statPages', st.pages);
      $('#heroMembers').textContent = fmt(st.members || 0) + ' pembaca';
      $('#heroPages').textContent = fmt(st.pages || 0) + ' halaman';
      if (!books.length) {
        row.innerHTML = '<div class="empty catalog-empty">' + ic('book') + '<strong>Belum ada buku yang sedang dibaca</strong><span>Jadilah yang pertama mencatat bacaan di komunitas.</span></div>';
        return;
      }
      row.innerHTML = books.map(function (b, i) {
        var p = pct(b.currentPage, b.totalPages);
        return '<article class="bk reveal" style="--d:' + (i * 70) + 'ms">' +
          '<div class="cover-wrap">' + coverHTML(b) + '</div>' +
          '<h3 class="clamp-2">' + esc(b.title) + '</h3>' +
          '<div class="au truncate">' + esc(b.author) + '</div>' +
          '<div class="foot"><div class="prog-lbl"><span>Progres</span><b>' + p + '%</b></div>' +
          '<div class="bar thin"><i data-w="' + p + '"></i></div>' +
          '<div class="reader">' + avatarHTML({ name: b.readerName, avatarURL: '' }, 'sm') + '<span class="truncate">' + esc(b.readerName) + '</span></div></div></article>';
      }).join('');
      hydrateIcons(row);
      requestAnimationFrame(function () { $$('.bar > i[data-w]', row).forEach(function (i) { i.style.width = i.getAttribute('data-w') + '%'; }); });
      observeReveals(row);
    }).catch(function (e) {
      row.innerHTML = '<div class="empty catalog-empty">' + ic('alert') + '<strong>Katalog belum dapat dimuat</strong><span>' + esc(errMsg(e)) + '</span></div>';
    });
  }

  function setCount(sel, target) {
    var el = $(sel);
    if (!el) return;
    var to = num(target), start = 0, t0 = null, dur = 1400;
    function step(ts) {
      if (!t0) t0 = ts;
      var k = Math.min(1, (ts - t0) / dur);
      var eased = 1 - Math.pow(1 - k, 3);
      el.textContent = fmt(Math.round(start + (to - start) * eased));
      if (k < 1) requestAnimationFrame(step);
    }
    requestAnimationFrame(step);
  }

  var revealIO = null;
  function observeReveals(root) {
    var nodes = $$('.reveal:not(.in)', root || document);
    if (!('IntersectionObserver' in window)) { nodes.forEach(function (n) { n.classList.add('in'); }); return; }
    if (!revealIO) {
      revealIO = new IntersectionObserver(function (entries) {
        entries.forEach(function (en) {
          if (en.isIntersecting) { en.target.classList.add('in'); revealIO.unobserve(en.target); }
        });
      }, { threshold: 0.12, rootMargin: '0px 0px -40px 0px' });
    }
    nodes.forEach(function (n) { revealIO.observe(n); });
  }

  function initLandingMotion() {
    var nav = $('#siteNav');
    function onScroll() { if (nav) nav.classList.toggle('scrolled', window.scrollY > 12); }
    window.addEventListener('scroll', onScroll, { passive: true });
    onScroll();
    var ring = $('#heroRing');
    if (ring) requestAnimationFrame(function () { setTimeout(function () { ring.style.strokeDashoffset = String(377 * (1 - 0.72)); }, 500); });
    var mt = $('#menuToggle'), mm = $('#mobileMenu');
    if (mt && mm) {
      mt.addEventListener('click', function () {
        var open = !mm.classList.contains('open');
        mm.classList.toggle('open', open);
        mt.setAttribute('aria-expanded', String(open));
        mt.setAttribute('aria-label', open ? 'Tutup menu' : 'Buka menu');
        mt.innerHTML = ic(open ? 'x' : 'menu');
      });
      $$('#mobileMenu a').forEach(function (a) { a.addEventListener('click', function () { mm.classList.remove('open'); mt.setAttribute('aria-expanded', 'false'); mt.innerHTML = ic('menu'); }); });
    }
    $$('.stat .kpi, .kpi[data-count]').forEach(function () {});
    observeReveals($('#marketingView'));
  }

  /* ------------------------------------------------------------------------
   * PERALIHAN LANDING <-> APLIKASI
   * ------------------------------------------------------------------------ */
  function showLanding() {
    buildLanding();
    $('#marketingView').hidden = false;
    $('#appView').hidden = true;
    document.body.classList.remove('in-app');
    stopCharts();
  }
  function showApp() {
    $('#marketingView').hidden = true;
    $('#appView').hidden = false;
    document.body.classList.add('in-app');
    window.scrollTo(0, 0);
  }

  /* Modal masuk, daftar, dan reset */
  function openLogin(note) {
    var m = openModal({
      title: 'Masuk ke Kelas Membaca',
      size: 'sm',
      body:
        (note ? '<p class="muted" style="margin-bottom:14px">' + esc(note) + '</p>' : '') +
        '<form id="loginForm" novalidate>' +
          '<div class="fg" style="margin-bottom:16px"><label class="lbl" for="lgId">Email atau username</label>' +
          '<input class="field" id="lgId" name="identifier" autocomplete="username" required></div>' +
          '<div class="fg" style="margin-bottom:8px"><label class="lbl" for="lgPw">Kata sandi</label>' +
          '<input class="field" id="lgPw" name="password" type="password" autocomplete="current-password" required></div>' +
          '<div class="err-text" id="lgErr" role="alert"></div>' +
          '<div class="row-wrap between" style="margin-top:10px"><button type="button" class="link-btn" data-go="reset">Lupa kata sandi?</button>' +
          '<button type="button" class="link-btn" data-go="register">Belum punya akun? Daftar</button></div>' +
        '</form>',
      foot: '<button type="submit" form="loginForm" class="btn btn-primary btn-block" id="lgSubmit">Masuk</button>'
    });
    var form = m.body.querySelector('#loginForm');
    form.addEventListener('submit', function (ev) {
      ev.preventDefault();
      var idv = form.querySelector("[name=identifier]").value.trim(), pw = form.querySelector("[name=password]").value;
      var err = m.body.querySelector('#lgErr');
      if (!idv || !pw) { err.textContent = 'Email/username dan kata sandi wajib diisi.'; return; }
      err.textContent = '';
      var btn = m.el.querySelector('#lgSubmit');
      setBusy(btn, true);
      doLogin(idv, pw).then(function () { m.close(); }).catch(function (e) {
        err.textContent = errMsg(e);
      }).then(function () { setBusy(btn, false); });
    });
    m.body.addEventListener('click', function (ev) {
      var g = ev.target.closest('[data-go]');
      if (!g) return;
      var target = g.getAttribute('data-go');
      m.close();
      if (target === 'register') openRegister();
      if (target === 'reset') openReset();
    });
  }

  function doLogin(identifier, password) {
    return api('login', { identifier: identifier, email: identifier, password: password }).then(function (d) {
      S.token = d.token; S.user = d.user; S.adminBackup = null;
      saveSession();
      toast(d.__m || 'Berhasil masuk.');
      return enterApp(true);
    });
  }

  function openRegister() {
    var m = openModal({
      title: 'Buat akun baru',
      size: 'sm',
      body:
        '<form id="regForm" novalidate>' +
          '<div class="fg" style="margin-bottom:16px"><label class="lbl" for="rgName">Nama lengkap<span class="req">*</span></label><input class="field" id="rgName" name="name" autocomplete="name" required maxlength="100"></div>' +
          '<div class="fg" style="margin-bottom:16px"><label class="lbl" for="rgEmail">Email<span class="req">*</span></label><input class="field" id="rgEmail" name="email" type="email" autocomplete="email" required></div>' +
          '<div class="fg" style="margin-bottom:16px"><label class="lbl" for="rgUser">Username <span class="muted small">(opsional)</span></label><input class="field" id="rgUser" name="username" autocomplete="username" maxlength="40" placeholder="otomatis dari nama jika kosong"></div>' +
          '<div class="fg" style="margin-bottom:8px"><label class="lbl" for="rgPw">Kata sandi<span class="req">*</span></label><input class="field" id="rgPw" name="password" type="password" autocomplete="new-password" required minlength="8"><span class="hint">Minimal 8 karakter, memuat huruf dan angka.</span></div>' +
          '<div class="err-text" id="rgErr" role="alert"></div>' +
        '</form>',
      foot: '<button type="submit" form="regForm" class="btn btn-primary btn-block" id="rgSubmit">Daftar sekarang</button>'
    });
    var form = m.body.querySelector('#regForm');
    form.addEventListener('submit', function (ev) {
      ev.preventDefault();
      var errEl = m.body.querySelector('#rgErr');
      var data = { name: form.querySelector('#rgName').value.trim(), email: form.querySelector('#rgEmail').value.trim(), username: form.querySelector('#rgUser').value.trim(), password: form.querySelector('#rgPw').value };
      if (data.name.length < 2) { errEl.textContent = 'Nama wajib diisi.'; return; }
      if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(data.email)) { errEl.textContent = 'Format email belum benar.'; return; }
      if (data.password.length < 8 || !/[A-Za-z]/.test(data.password) || !/[0-9]/.test(data.password)) { errEl.textContent = 'Kata sandi minimal 8 karakter dan memuat huruf serta angka.'; return; }
      errEl.textContent = '';
      var btn = m.el.querySelector('#rgSubmit');
      setBusy(btn, true);
      api('register', data).then(function (d) {
        S.token = d.token; S.user = d.user; S.adminBackup = null;
        saveSession();
        m.close();
        toast(d.__m || 'Akun berhasil dibuat.');
        return enterApp(true);
      }).catch(function (e) {
        errEl.textContent = errMsg(e);
        setBusy(btn, false);
      });
    });
  }

  function openReset() {
    var step = 1, ident = '';
    var m = openModal({
      title: 'Atur ulang kata sandi',
      size: 'sm',
      body: '',
      foot: ''
    });
    function renderStep() {
      if (step === 1) {
        m.body.innerHTML =
          '<form id="rsForm" novalidate><p class="muted" style="margin-bottom:16px">Masukkan email atau username. Kami akan mengirim kode 6 digit ke email Anda.</p>' +
          '<div class="fg"><label class="lbl" for="rsId">Email atau username</label><input class="field" id="rsId" required autocomplete="username"></div>' +
          '<div class="err-text" id="rsErr" role="alert"></div></form>';
        m.el.querySelector('.modal-foot') && m.el.querySelector('.modal-foot').remove();
        m.el.querySelector('.modal-card').insertAdjacentHTML('beforeend', '<div class="modal-foot"><button type="submit" form="rsForm" class="btn btn-primary btn-block" id="rsSend">Kirim kode</button></div>');
        var f = m.body.querySelector('#rsForm');
        f.addEventListener('submit', function (ev) {
          ev.preventDefault();
          ident = f.querySelector('#rsId').value.trim();
          var err = m.body.querySelector('#rsErr');
          if (!ident) { err.textContent = 'Email atau username wajib diisi.'; return; }
          var btn = m.el.querySelector('#rsSend');
          setBusy(btn, true);
          api('requestPasswordReset', { identifier: ident }).then(function (d) {
            toast(d.__m || 'Jika akun ditemukan, kode telah dikirim.', 'info');
            step = 2; renderStep();
          }).catch(function (e) { err.textContent = errMsg(e); }).then(function () { setBusy(btn, false); });
        });
      } else {
        m.body.innerHTML =
          '<form id="rsForm2" novalidate><p class="muted" style="margin-bottom:16px">Masukkan kode 6 digit dan kata sandi baru Anda. Kode berlaku 15 menit.</p>' +
          '<div class="fg" style="margin-bottom:16px"><label class="lbl" for="rsCode">Kode reset</label><input class="field" id="rsCode" inputmode="numeric" autocomplete="one-time-code" maxlength="6" required></div>' +
          '<div class="fg"><label class="lbl" for="rsNew">Kata sandi baru</label><input class="field" id="rsNew" type="password" autocomplete="new-password" minlength="8" required><span class="hint">Minimal 8 karakter, memuat huruf dan angka.</span></div>' +
          '<div class="err-text" id="rsErr2" role="alert"></div></form>';
        m.el.querySelector('.modal-foot') && m.el.querySelector('.modal-foot').remove();
        m.el.querySelector('.modal-card').insertAdjacentHTML('beforeend', '<div class="modal-foot"><button type="submit" form="rsForm2" class="btn btn-primary btn-block" id="rsSave">Simpan kata sandi</button></div>');
        var f2 = m.body.querySelector('#rsForm2');
        f2.addEventListener('submit', function (ev) {
          ev.preventDefault();
          var err = m.body.querySelector('#rsErr2');
          var code = f2.querySelector('#rsCode').value.trim(), pw = f2.querySelector('#rsNew').value;
          if (!/^\d{6}$/.test(code)) { err.textContent = 'Kode harus 6 digit angka.'; return; }
          if (pw.length < 8 || !/[A-Za-z]/.test(pw) || !/[0-9]/.test(pw)) { err.textContent = 'Kata sandi minimal 8 karakter dan memuat huruf serta angka.'; return; }
          var btn = m.el.querySelector('#rsSave');
          setBusy(btn, true);
          api('confirmPasswordReset', { identifier: ident, code: code, newPassword: pw }).then(function (d) {
            m.close();
            toast(d.__m || 'Kata sandi berhasil diperbarui.');
            openLogin();
          }).catch(function (e) { err.textContent = errMsg(e); }).then(function () { setBusy(btn, false); });
        });
      }
    }
    renderStep();
  }

  /* ------------------------------------------------------------------------
   * ROUTER
   * ------------------------------------------------------------------------ */
  function parseHash() {
    var h = (location.hash || '').replace(/^#/, '');
    if (h.charAt(0) !== '/') return null;
    var parts = h.replace(/^\/+/, '').split('/');
    return { page: parts[0] || 'home', id: decodeURIComponent(parts[1] || '') };
  }
  function go(hash) {
    if (location.hash === hash) { route(); return; }
    location.hash = hash;
  }

  function route() {
    if (!S.token || !S.user) {
      showLanding();
      var r0 = parseHash();
      if (r0) {
        if (window.location.hash !== '#/') history.replaceState(null, '', '#/');
        openLogin('Silakan masuk untuk membuka halaman ini.');
      } else if (location.hash && location.hash.length > 1) {
        var el = document.getElementById(location.hash.slice(1));
        if (el) setTimeout(function () { el.scrollIntoView({ behavior: 'smooth', block: 'start' }); }, 40);
      }
      return;
    }
    showApp();
    var r = parseHash() || { page: 'home', id: '' };
    var known = ['home', 'buku', 'jelajah', 'kelas', 'tugas', 'peringkat', 'profil', 'admin'];
    if (known.indexOf(r.page) < 0) { go('#/home'); return; }
    if (r.page === 'admin' && !isAdmin()) { toast('Halaman ini khusus admin.', 'error'); go('#/home'); return; }
    S.route = r;
    renderShell();
    renderRoute(r);
  }

  /* Gabungan: penerapan sesi masuk ke dashboard */
  function enterApp(fromLogin) {
    return refreshDashboard().then(function () {
      if (fromLogin && (!location.hash || parseHash() === null)) location.hash = '#/home';
      else route();
      if (fromLogin) restoreTimerIfAny();
    });
  }

  function refreshDashboard() {
    return api('getDashboard', {}).then(function (d) {
      S.dash = d;
      if (d.user) { S.user = d.user; saveSession(); }
      return d;
    });
  }

  window.KM = {
    CFG: CFG, S: S, $: $, $$: $$, esc: esc, ic: ic, api: api, apiGet: apiGet, toast: toast, openModal: openModal,
    confirmDialog: confirmDialog, setBusy: setBusy, errMsg: errMsg, num: num, fmt: fmt, pct: pct, initials: initials,
    avatarHTML: avatarHTML, dayKey: dayKey, todayKey: todayKey, addDays: addDays, fmtDate: fmtDate, fmtTime: fmtTime,
    fmtDur: fmtDur, timeHM: timeHM, debounce: debounce, readFileAsDataURL: readFileAsDataURL, compressCover: compressCover,
    coverHTML: coverHTML, colorFor: colorFor, hydrateIcons: hydrateIcons, observeReveals: observeReveals,
    go: go, route: route, parseHash: parseHash, refreshDashboard: refreshDashboard, saveSession: saveSession,
    isAdmin: isAdmin, stopCharts: stopCharts, openLogin: openLogin, openRegister: openRegister, openReset: openReset,
    clearSession: clearSession, expireSession: expireSession, closeAllModals: closeAllModals, closeTopModal: closeTopModal,
    TIMER_KEY: TIMER_KEY, TZ: TZ, enterApp: enterApp, showLanding: showLanding, showApp: showApp, doLogin: doLogin,
    loadSession: loadSession, clearSessionStorage: clearSession, apiReady: apiReady
  };
  /* ==========================================================================
   APLIKASI — SHELL (sidebar desktop, bottom nav mobile, FAB "Baca")
   ========================================================================== */
  var NAV = [
    { id: 'home', label: 'Beranda', icon: 'home' },
    { id: 'buku', label: 'Rak Buku', icon: 'book' },
    { id: 'jelajah', label: 'Jelajah', icon: 'globe' },
    { id: 'kelas', label: 'Kelas', icon: 'class' },
    { id: 'tugas', label: 'Tugas', icon: 'task' },
    { id: 'peringkat', label: 'Peringkat', icon: 'trophy' },
    { id: 'profil', label: 'Profil', icon: 'user' },
    { id: 'admin', label: 'Admin', icon: 'shield', admin: true }
  ];
  var PAGE_TITLES = { home: 'Beranda', buku: 'Rak Buku', jelajah: 'Jelajah', kelas: 'Kelas', tugas: 'Tugas', peringkat: 'Peringkat', profil: 'Profil', admin: 'Admin' };

  function renderShell() {
    if (S.appBuilt) { updateNav(); renderSideUser(); renderImpBanner(); return; }
    S.appBuilt = true;
    var links = NAV.map(function (n) {
      return '<button type="button" data-nav="' + n.id + '"' + (n.admin ? ' data-admin="1"' : '') + '>' + ic(n.icon) + '<span>' + esc(n.label) + '</span></button>';
    }).join('');
    $('#appView').innerHTML =
      '<aside class="side" aria-label="Navigasi utama"><div class="sidebar-inner">' +
        '<a class="brand" href="#/home"><span class="brand-mark">' + ic('book-open') + '</span><span>Kelas Membaca<small>Bangun kebiasaan membaca</small></span></a>' +
        '<nav class="side-nav" id="sideNav" aria-label="Menu">' + links + '</nav>' +
        '<div class="side-timer"><p>Siap membaca? Mulai timer fokus.</p><button type="button" class="btn btn-mint btn-block" data-act="timer-setup">' + ic('play') + ' Baca sekarang</button></div>' +
        '<div class="side-user" id="sideUser"></div>' +
        '<div class="side-foot"><button type="button" class="btn btn-outline" data-act="logout">' + ic('logout') + ' Keluar</button></div>' +
      '</div></aside>' +
      '<header class="topbar"><a class="brand" href="#/home" aria-label="Beranda"><span class="brand-mark" style="width:36px;height:36px;border-radius:12px">' + ic('book-open') + '</span></a>' +
        '<h1 class="title" id="topTitle">Beranda</h1>' +
        '<button type="button" class="btn btn-icon" data-act="logout" aria-label="Keluar">' + ic('logout') + '</button></header>' +
      '<div id="impBanner"></div>' +
      '<main class="app-main" id="appMain" tabindex="-1"><div id="pageRoot"></div></main>' +
      '<nav class="bottomnav" aria-label="Navigasi bawah">' +
        '<button type="button" class="bn" data-nav="home">' + ic('home') + '<span>Beranda</span></button>' +
        '<button type="button" class="bn" data-nav="buku">' + ic('book') + '<span>Rak</span></button>' +
        '<div class="fab-wrap"><button type="button" class="fab" data-act="timer-setup" aria-label="Baca: mulai timer">' + ic('play') + '</button><span class="fab-lbl" style="display:none"></span></div>' +
        '<button type="button" class="bn" data-nav="jelajah">' + ic('globe') + '<span>Jelajah</span></button>' +
        '<button type="button" class="bn" data-act="more">' + ic('more') + '<span>Lainnya</span></button>' +
      '</nav>';
    $('#appView').addEventListener('click', onAppClick);
    renderSideUser();
    updateNav();
    renderImpBanner();
  }

  function updateNav() {
    var cur = S.route.page;
    $$('[data-nav]').forEach(function (b) {
      var id = b.getAttribute('data-nav');
      var admin = b.getAttribute('data-admin') === '1';
      if (admin && !isAdmin()) { b.style.display = 'none'; return; }
      b.style.display = '';
      var on = id === cur;
      b.classList.toggle('active', on);
      if (b.closest('.side-nav')) { if (on) b.setAttribute('aria-current', 'page'); else b.removeAttribute('aria-current'); }
      if (b.closest('.bottomnav') && on) b.setAttribute('aria-current', 'page'); else if (b.closest('.bottomnav')) b.removeAttribute('aria-current');
    });
    var t = $('#topTitle');
    if (t) t.textContent = cur === 'buku' && S.route.id ? 'Detail Buku' : (PAGE_TITLES[cur] || 'Beranda');
  }

  function renderSideUser() {
    var box = $('#sideUser');
    if (!box || !S.user) return;
    box.innerHTML = avatarHTML(S.user, '') + '<div class="su-info"><b>' + esc(S.user.name) + '</b><span>@' + esc(S.user.username) + (isAdmin() ? ' · Admin' : '') + '</span></div>';
  }

  function renderImpBanner() {
    var b = $('#impBanner');
    if (!b) return;
    if (!S.adminBackup) { b.innerHTML = ''; return; }
    b.innerHTML = '<div class="row-wrap between" style="margin:12px 16px 0;padding:12px 16px;border-radius:16px;background:var(--warn-soft);border:1px solid #FDE6B3">' +
      '<span style="font-size:15px"><b>Mode penyamaran:</b> Anda sedang melihat akun ' + esc(S.user.name) + '.</span>' +
      '<button type="button" class="btn btn-sm btn-gold" data-act="imp-exit">' + ic('arrow-left') + ' Kembali ke admin</button></div>';
  }

  function ensureDash(cb) {
    if (S.dash) { cb(); return; }
    setPage('<div class="skeleton" style="height:220px;margin-bottom:16px"></div><div class="skeleton" style="height:320px"></div>');
    refreshDashboard().then(cb).catch(function (e) {
      setPage('<div class="empty">' + ic('alert') + '<strong>Data belum dapat dimuat</strong><span>' + esc(errMsg(e)) + '</span><button class="btn btn-primary" data-act="retry">' + ic('refresh') + ' Coba lagi</button></div>');
    });
  }

  function setPage(html) {
    var root = $('#pageRoot');
    if (!root) return;
    stopCharts();
    root.innerHTML = '<div class="view">' + html + '</div>';
    hydrateIcons(root);
    observeReveals(root);
    requestAnimationFrame(function () { $$('[data-w]', root).forEach(function (n) { n.style.width = n.getAttribute('data-w') + '%'; }); });
  }

  /* Dipanggil router setelah sesi siap */
  function renderRoute(r) {
    var map = {
      home: pageHome, buku: function () { return r.id ? pageBookDetail(r.id) : pageBooks(); },
      jelajah: pageExplore, kelas: pageClasses, tugas: pageTasks, peringkat: pageLeaderboard,
      profil: pageProfile, admin: pageAdmin
    };
    var fn = map[r.page] || pageHome;
    var token = (S.renderToken = (S.renderToken || 0) + 1);
    ensureDash(function () { if (token === S.renderToken) fn(); });
    window.scrollTo({ top: 0, behavior: 'auto' });
  }

  /* Event delegasi global aplikasi */
  function onAppClick(ev) {
    var t = ev.target.closest('[data-act],[data-nav]');
    if (!t) return;
    var act = t.getAttribute('data-act');
    var nav = t.getAttribute('data-nav');
    if (nav) { go('#/' + nav); return; }
    if (act) handleAct(act, t, ev);
  }

  function handleAct(act, t, ev) {
    var id = t.getAttribute('data-id') || '';
    switch (act) {
      case 'logout': return doLogout();
      case 'retry': return route();
      case 'more': return openMoreSheet();
      case 'timer-setup': return openTimerSetup();
      case 'imp-exit': return exitImpersonation();
      case 'book-add': return openBookForm(null);
      case 'book-edit': return openBookForm(findMyBook(id));
      case 'book-del': return deleteBook(id);
      case 'book-read': return openTimerSetup(findBookAny(id));
      case 'book-log': return openLogForm({ book: findMyBook(id) });
      case 'book-open': return go('#/buku/' + encodeURIComponent(id));
      case 'filter-status': S.filter.status = t.getAttribute('data-v'); return pageBooks();
      case 'log-edit': return openLogForm({ log: findLog(id) });
      case 'log-del': return deleteLog(id);
      case 'comment-del': return deleteComment(id, t.getAttribute('data-log'));
      case 'friend': return toggleFriend(id, t);
      case 'shelf': return openShelf(id);
      case 'explore-tab': S.explore.tab = t.getAttribute('data-v'); S.explore.topic = ''; return pageExplore();
      case 'explore-topic': S.explore.topic = t.getAttribute('data-v'); S.explore.tab = 'topik'; return pageExplore();
      case 'user-progress': return openMemberProgress(id);
      case 'lb-class': S.lbClass = t.getAttribute('data-v') || ''; return pageLeaderboard();
      case 'lb-days': S.lbDays = Number(t.getAttribute('data-v')) || 30; return pageLeaderboard();
      case 'class-add': return openClassForm(null);
      case 'class-edit': return openClassForm(findClass(id));
      case 'class-del': return deleteClass(id);
      case 'class-join': return joinClass(id, t);
      case 'class-members': return openClassMembers(id);
      case 'class-board': S.lbClass = id; go('#/peringkat'); return;
      case 'class-gen': return generateTasks(id, t);
      case 'task-add': return openTaskForm(null);
      case 'task-edit': return openTaskForm(findTask(id));
      case 'task-del': return deleteTask(id);
      case 'task-submit': return openSubmitForm(findTask(id));
      case 'task-subs': return openSubmissions(findTask(id));
      case 'task-filter': S.tasksClass = t.getAttribute('data-v') || ''; return pageTasks();
      case 'user-add': return openUserForm(null);
      case 'user-edit': return openUserForm(findUser(id));
      case 'user-del': return deleteUser(id);
      case 'user-imp': return impersonate(id);
      case 'admin-tab': S.adminTab = t.getAttribute('data-v'); return pageAdmin();
      case 'admin-user-q': return;
      case 'lifecycle': return runLifecycle(t);
      case 'backup-export': return exportBackup(t);
      case 'backup-import': return document.getElementById('importPicker').click();
      case 'cover-del-form': return;
      case 'log-remove-cover': return;
      default: return;
    }
  }

  /* Pencarian data lokal */
  function findMyBook(id) { return (S.dash && S.dash.myBooks || []).filter(function (b) { return b.bookId === id; })[0] || null; }
  function findBookAny(id) {
    var d = S.dash || {};
    return (d.myBooks || []).concat(d.communityBooks || []).filter(function (b) { return b.bookId === id; })[0] || null;
  }
  function findLog(id) { return (S.dash && S.dash.myLogs || []).filter(function (l) { return l.logId === id; })[0] || null; }
  function findClass(id) { return (S.dash && S.dash.classes || []).filter(function (c) { return c.classId === id; })[0] || null; }
  function findTask(id) { return (S.dash && S.dash.tasks || []).filter(function (t) { return t.taskId === id; })[0] || null; }
  function findUser(id) { return (S.dash && S.dash.users || []).filter(function (u) { return u.userId === id; })[0] || null; }

  function doLogout() {
    confirmDialog('Keluar dari akun?', 'Sesi di perangkat ini akan diakhiri. Timer yang sedang berjalan tetap tersimpan.', 'Keluar', false).then(function (ok) {
      if (!ok) return;
      var tok = S.token;
      if (tok) api('logout', {}).catch(function () { /* abaikan */ });
      clearSession();
      stopCharts();
      closeAllModals();
      hideTimerUI();
      S.appBuilt = false;
      $('#appView').innerHTML = '';
      $('#appView').removeEventListener('click', onAppClick);
      toast('Anda sudah keluar. Sampai jumpa lagi!', 'info');
      location.hash = '#/';
      showLanding();
    });
  }

  function openMoreSheet() {
    var items = NAV.slice(3).filter(function (n) { return !n.admin || isAdmin(); });
    var html = '<div class="grid-2" style="grid-template-columns:1fr 1fr;gap:10px">' + items.map(function (n) {
      return '<button type="button" class="btn btn-soft" style="justify-content:flex-start;min-height:56px" data-go="' + n.id + '">' + ic(n.icon) + esc(n.label) + '</button>';
    }).join('') + '</div>';
    var m = openModal({ title: 'Menu lainnya', size: 'sm', body: html, foot: '' });
    m.body.addEventListener('click', function (ev) {
      var b = ev.target.closest('[data-go]');
      if (!b) return;
      m.close(); go('#/' + b.getAttribute('data-go'));
    });
  }

  /* ==========================================================================
   * HALAMAN: BERANDA
   * ========================================================================== */
  function sumBy(arr, key) { return arr.reduce(function (s, x) { return s + num(x[key]); }, 0); }

  function calcStreak(logs) {
    var days = {};
    logs.forEach(function (l) { if (l.date) days[l.date] = true; });
    var k = todayKey();
    if (!days[k]) k = addDays(k, -1);
    var n = 0;
    while (days[k]) { n++; k = addDays(k, -1); }
    return n;
  }

  function greeting() {
    var h = Number(new Date().toLocaleString('en-GB', { hour: '2-digit', hour12: false, timeZone: TZ }));
    if (h < 11) return 'Selamat pagi';
    if (h < 15) return 'Selamat siang';
    if (h < 18) return 'Selamat sore';
    return 'Selamat malam';
  }

  function pageHome() {
    var d = S.dash, me = S.user, today = todayKey();
    var logs = d.myLogs || [], books = d.myBooks || [];
    var totalPages = sumBy(logs, 'pagesRead'), totalMin = sumBy(logs, 'effectiveMinutes');
    var finished = books.filter(function (b) { return b.status === 'Finished'; }).length;
    var streak = calcStreak(logs);
    var todayPages = sumBy(logs.filter(function (l) { return l.date === today; }), 'pagesRead');
    var target = CFG.TARGET_PAGES;
    var reading = books.filter(function (b) { return b.status !== 'Finished'; })
      .sort(function (a, b) { return String(b.updatedAt || '').localeCompare(String(a.updatedAt || '')); });
    var tp = pct(todayPages, target);

    var kpis =
      '<button type="button" class="kpi-card" data-nav="buku" aria-label="Lihat rak buku">' + ic('book', 'k-ic') + '<span class="k-lbl">Halaman dibaca</span><span class="kpi">' + fmt(totalPages) + '</span>' + ic('arrow-right', 'go ic-sm') + '</button>' +
      '<div class="kpi-card mint">' + ic('clock', 'k-ic') + '<span class="k-lbl">Menit efektif</span><span class="kpi">' + fmt(totalMin) + '</span></div>' +
      '<div class="kpi-card pink">' + ic('flame', 'k-ic') + '<span class="k-lbl">Streak membaca</span><span class="kpi">' + fmt(streak) + ' <span class="small muted">hari</span></span></div>' +
      '<div class="kpi-card gold">' + ic('award', 'k-ic') + '<span class="k-lbl">Buku selesai</span><span class="kpi">' + fmt(finished) + '</span></div>';

    var activeCards = reading.length ? reading.slice(0, 8).map(function (b) {
      return '<div class="active-card">' +
        '<div class="ac-cover" data-act="book-open" data-id="' + esc(b.bookId) + '" role="button" tabindex="0" aria-label="Buka ' + esc(b.title) + '">' + coverHTML(b) + '</div>' +
        '<div class="ac-body"><h3 class="clamp-2" data-act="book-open" data-id="' + esc(b.bookId) + '">' + esc(b.title) + '</h3>' +
        '<div class="meta truncate">' + esc(b.author) + '</div>' +
        '<div class="bar thin"><i data-w="' + pct(b.currentPage, b.totalPages) + '"></i></div>' +
        '<div class="meta">Hal ' + fmt(b.currentPage) + ' / ' + fmt(b.totalPages) + ' · ' + pct(b.currentPage, b.totalPages) + '%</div>' +
        '<div class="ac-actions"><button type="button" class="btn btn-soft btn-xs" data-act="book-log" data-id="' + esc(b.bookId) + '">' + ic('edit', 'ic-sm') + ' Catat</button>' +
        '<button type="button" class="play" data-act="book-read" data-id="' + esc(b.bookId) + '" aria-label="Mulai baca ' + esc(b.title) + '">' + ic('play') + '</button></div></div></div>';
    }).join('') : '<div class="empty" style="width:100%">' + ic('book') + '<strong>Belum ada buku yang sedang dibaca</strong><span>Tambahkan buku ke rak Anda untuk mulai membaca.</span><button class="btn btn-primary" data-act="book-add">' + ic('plus') + ' Tambah buku</button></div>';

    var recos = buildRecommendations(logs, books, reading, todayPages, streak);
    var feed = (d.communityLogs || []).slice(0, 8);

    setPage(
      '<section class="hello reveal">' +
        '<div><span class="eyebrow">' + esc(greeting()) + '</span><h1 style="margin-top:6px">Halo, ' + esc((me.name || '').split(' ')[0]) + '!</h1>' +
        '<p>' + (todayPages ? 'Hari ini Anda sudah membaca <b>' + fmt(todayPages) + '</b> dari <b>' + target + '</b> halaman.' : 'Target hari ini: <b>' + target + '</b> halaman. Yuk mulai!') + '</p></div>' +
        '<button type="button" class="btn btn-primary btn-lg shine" data-act="timer-setup">' + ic('play') + ' Mulai membaca</button>' +
      '</section>' +
      '<section class="kpi-grid reveal" style="--d:80ms" aria-label="Ringkasan">' + kpis + '</section>' +
      '<div class="dash-grid">' +
        '<div class="dash-col">' +
          '<section class="card reveal" aria-labelledby="hTarget">' +
            '<div class="card-title"><div><h2 id="hTarget">Target hari ini</h2><p>' + fmt(todayPages) + ' / ' + target + ' halaman</p></div><span class="pill ' + (tp >= 100 ? 'pill-ok' : 'pill-mint') + '">' + tp + '%</span></div>' +
            '<div class="bar"><i data-w="' + tp + '"></i></div>' +
          '</section>' +
          '<section class="card reveal" aria-labelledby="hLanjut">' +
            '<div class="card-title"><div><h2 id="hLanjut">Lanjut membaca</h2><p>Geser untuk melihat semua buku aktif</p></div><button class="btn btn-ghost btn-sm" data-nav="buku">Rak buku ' + ic('arrow-right', 'ic-sm') + '</button></div>' +
            '<div class="carousel" role="list">' + activeCards + '</div>' +
          '</section>' +
          '<section class="card reveal" aria-labelledby="hGrafik">' +
            '<div class="card-title"><div><h2 id="hGrafik">Grafik 14 hari</h2><p>Halaman dan menit efektif per hari</p></div>' +
              '<div class="legend"><span><i style="background:#F4A3B8"></i> Halaman</span><span><i style="background:#88DCD6"></i> Menit</span></div></div>' +
            '<div class="chart-box"><canvas id="chartDaily" role="img" aria-label="Grafik halaman dan menit membaca 14 hari terakhir"></canvas></div>' +
          '</section>' +
        '</div>' +
        '<div class="dash-col">' +
          '<section class="card reveal" aria-labelledby="hReco">' +
            '<div class="card-title"><div><h2 id="hReco">Rekomendasi untuk Anda</h2><p>Diperbarui otomatis dari aktivitas Anda</p></div></div>' +
            '<div class="recos">' + recos + '</div>' +
          '</section>' +
          '<section class="card reveal" aria-labelledby="hKal">' +
            '<div class="card-title"><div><h2 id="hKal">Kalender 30 hari</h2><p>Semakin pekat, semakin banyak halaman</p></div></div>' +
            buildCalendar(logs, today) +
          '</section>' +
          '<section class="card reveal" aria-labelledby="hFeed">' +
            '<div class="card-title"><div><h2 id="hFeed">Aktivitas komunitas</h2><p>Catatan terbaru dari anggota</p></div><button class="btn btn-ghost btn-sm" data-nav="jelajah">Jelajah ' + ic('arrow-right', 'ic-sm') + '</button></div>' +
            (feed.length ? '<div class="feed">' + feed.map(function (l, i) { return feedItem(l, i); }).join('') + '</div>' : '<div class="empty">' + ic('message') + '<strong>Belum ada aktivitas</strong><span>Catatan publik dari anggota akan tampil di sini.</span></div>') +
          '</section>' +
        '</div>' +
      '</div>'
    );
    drawDailyChart(logs);
  }

  function buildRecommendations(logs, books, reading, todayPages, streak) {
    var out = [];
    var today = todayKey();
    var target = CFG.TARGET_PAGES;
    if (!logs.some(function (l) { return l.date === today; })) {
      out.push({ tone: 'warn', icon: 'clock', t: 'Catat bacaan hari ini', p: 'Belum ada catatan untuk hari ini. Mulai timer dan selesaikan satu sesi kecil.' });
    } else if (todayPages < target) {
      out.push({ tone: 'info', icon: 'target', t: 'Tinggal ' + fmt(target - todayPages) + ' halaman lagi', p: 'Anda sudah di ' + pct(todayPages, target) + '% target harian. Sedikit lagi!' });
    }
    if (streak >= 3) out.push({ tone: 'ok', icon: 'flame', t: 'Streak ' + streak + ' hari beruntun', p: 'Pertahankan ritme ini. Jangan putus rantainya.' });
    var stalled = reading.filter(function (b) {
      var last = logs.filter(function (l) { return l.bookId === b.bookId; }).map(function (l) { return l.date; }).sort().pop();
      return !last || last < addDays(today, -7);
    })[0];
    if (stalled) out.push({ tone: 'warn', icon: 'book', t: 'Buku "' + stalled.title + '" mulai terbengkalai', p: 'Belum ada catatan lebih dari seminggu. Lanjutkan dari halaman ' + fmt(stalled.currentPage + 1) + '.', bookId: stalled.bookId });
    var recent = logs.filter(function (l) { return l.date >= addDays(today, -30); });
    var topics = {};
    recent.forEach(function (l) { topics[l.topic || 'umum'] = true; });
    if (recent.length >= 3 && Object.keys(topics).length < 2) out.push({ tone: 'mint', icon: 'layers', t: 'Coba topik baru', p: 'Bacaan Anda masih berpusat di satu topik. Jelajahi topik lain di komunitas.', go: '#/jelajah' });
    if (!out.length) out.push({ tone: 'ok', icon: 'award', t: 'Kerja bagus hari ini!', p: 'Semua rekomendasi terpenuhi. Nikmati bacaan Anda.' });
    return out.map(function (r, i) {
      var action = r.bookId ? ' data-act="book-open" data-id="' + esc(r.bookId) + '" role="button" tabindex="0" style="cursor:pointer"' : (r.go ? ' data-nav-go="' + esc(r.go) + '" role="button" tabindex="0" style="cursor:pointer"' : '');
      return '<div class="reco tone-' + r.tone + '" style="--i:' + i + '"' + action + '><span class="ric">' + ic(r.icon) + '</span><div><b>' + esc(r.t) + '</b><p>' + esc(r.p) + '</p></div></div>';
    }).join('');
  }

  function buildCalendar(logs, today) {
    var perDay = {};
    logs.forEach(function (l) { perDay[l.date] = (perDay[l.date] || 0) + num(l.pagesRead); });
    var start = addDays(today, -29);
    var lead = (new Date(start + 'T12:00:00Z').getUTCDay() + 6) % 7;
    var html = ['Sen', 'Sel', 'Rab', 'Kam', 'Jum', 'Sab', 'Min'].map(function (x) { return '<div class="dn">' + x + '</div>'; }).join('');
    for (var i = 0; i < lead; i++) html += '<div></div>';
    var target = CFG.TARGET_PAGES;
    for (var k = 0; k < 30; k++) {
      var key = addDays(start, k), p = perDay[key] || 0;
      var cls = p <= 0 ? '' : (p < target / 2 ? 'l1' : (p < target ? 'l2' : 'l3'));
      if (key === today) cls += ' today';
      var day = Number(key.slice(8, 10));
      html += '<div class="day ' + cls + '" title="' + fmtDate(key) + ': ' + fmt(p) + ' halaman" aria-label="' + fmtDate(key) + ', ' + fmt(p) + ' halaman">' + day + '</div>';
    }
    return '<div class="cal">' + html + '</div>' +
      '<div class="legend" style="margin-top:14px"><span><i style="background:#F2F4F7"></i> Kosong</span><span><i style="background:#D9F5F2"></i> Sedikit</span><span><i style="background:#8EE3DC"></i> Sedang</span><span><i style="background:var(--grad-mint)"></i> Target tercapai</span></div>';
  }

  function feedItem(l, i) {
    return '<article class="feed-item" style="--i:' + i + '" data-act="book-open" data-id="' + esc(l.bookId) + '" role="button" tabindex="0">' +
      '<div class="fcover">' + coverHTML({ title: l.bookTitle, author: l.author, coverURL: l.coverURL, status: '' }, { cls: 'cover-sm' }) + '</div>' +
      '<div class="fbody">' +
        '<div class="fhead">' + avatarHTML({ name: l.userName, avatarURL: l.userAvatar }, 'sm') + '<span><b>' + esc(l.userName) + '</b> membaca <b>' + esc(l.bookTitle) + '</b></span><span class="ftime">' + fmtDate(l.date) + '</span></div>' +
        (l.insight ? '<blockquote class="clamp-3">' + esc(l.insight) + '</blockquote>' : '') +
        '<div class="fmeta"><span class="pill">' + fmt(l.pagesRead) + ' hal</span><span class="pill pill-mint">' + fmtDur(l.effectiveMinutes) + '</span>' +
        '<button type="button" class="topic-chip" data-act="explore-topic" data-v="' + esc(l.topic) + '">#' + esc(l.topic) + '</button>' +
        '<span class="muted">' + fmt(l.commentsCount) + ' komentar</span></div>' +
      '</div></article>';
  }

  function drawDailyChart(logs) {
    var canvas = document.getElementById('chartDaily');
    if (!canvas) return;
    if (!window.Chart) { canvas.parentNode.innerHTML = '<p class="muted">Grafik membutuhkan Chart.js. Periksa koneksi internet Anda.</p>'; return; }
    var today = todayKey(), labels = [], pages = [], mins = [];
    for (var i = 13; i >= 0; i--) {
      var k = addDays(today, -i);
      labels.push(fmtDate(k, false));
      var dl = logs.filter(function (l) { return l.date === k; });
      pages.push(sumBy(dl, 'pagesRead'));
      mins.push(sumBy(dl, 'effectiveMinutes'));
    }
    var chart = new window.Chart(canvas, {
      type: 'bar',
      data: {
        labels: labels,
        datasets: [
          { label: 'Halaman', data: pages, backgroundColor: '#F4A3B8', borderRadius: 8, yAxisID: 'y', maxBarThickness: 26 },
          { label: 'Menit efektif', data: mins, backgroundColor: '#88DCD6', borderRadius: 8, yAxisID: 'y1', maxBarThickness: 26 }
        ]
      },
      options: {
        responsive: true, maintainAspectRatio: false,
        interaction: { mode: 'index', intersect: false },
        plugins: { legend: { display: false }, tooltip: { bodyFont: { size: 15 }, titleFont: { size: 15 } } },
        scales: {
          x: { ticks: { font: { size: 13 }, color: '#667085', maxRotation: 0, autoSkip: true }, grid: { display: false } },
          y: { position: 'left', beginAtZero: true, ticks: { font: { size: 14 }, color: '#667085', precision: 0 }, grid: { color: '#F2F4F7' }, title: { display: true, text: 'Halaman', font: { size: 14 }, color: '#B54708' } },
          y1: { position: 'right', beginAtZero: true, ticks: { font: { size: 14 }, color: '#667085', precision: 0 }, grid: { drawOnChartArea: false }, title: { display: true, text: 'Menit', font: { size: 14 }, color: '#0B7A73' } }
        },
        animation: { duration: 900, easing: 'easeOutQuart' }
      }
    });
    S.charts.push(chart);
  }

  /* ==========================================================================
   * HALAMAN: RAK BUKU
   * ========================================================================== */
  function pageBooks() {
    var all = S.dash.myBooks || [];
    var st = S.filter.status, q = S.filter.q.toLowerCase();
    var cnt = { all: all.length, reading: all.filter(function (b) { return b.status !== 'Finished'; }).length, done: all.filter(function (b) { return b.status === 'Finished'; }).length };
    var list = all.filter(function (b) {
      if (st === 'reading' && b.status === 'Finished') return false;
      if (st === 'done' && b.status !== 'Finished') return false;
      return !q || (b.title + ' ' + b.author + ' ' + b.topic).toLowerCase().indexOf(q) >= 0;
    });
    var seg = function (v, lbl, n) { return '<button type="button" role="tab" aria-selected="' + (st === v) + '" class="' + (st === v ? 'active' : '') + '" data-act="filter-status" data-v="' + v + '">' + lbl + ' <span class="muted">' + n + '</span></button>'; };
    var cards = list.map(function (b, i) {
      var p = pct(b.currentPage, b.totalPages);
      return '<article class="bcard-app reveal" style="--d:' + (i * 50) + 'ms">' +
        '<div class="c-cover" data-act="book-open" data-id="' + esc(b.bookId) + '" role="button" tabindex="0" aria-label="Detail ' + esc(b.title) + '">' + coverHTML(b, { progress: true }) + '</div>' +
        '<div><h3 data-act="book-open" data-id="' + esc(b.bookId) + '" role="button" tabindex="0">' + esc(b.title) + '</h3><div class="au">' + esc(b.author) + '</div></div>' +
        '<div><div class="bar thin"><i data-w="' + p + '"></i></div><div class="small muted" style="margin-top:6px">' + fmt(b.currentPage) + ' / ' + fmt(b.totalPages) + ' hal · ' + p + '%</div></div>' +
        '<div class="bk-actions">' +
          '<button type="button" class="btn btn-mint btn-xs" data-act="book-read" data-id="' + esc(b.bookId) + '" aria-label="Baca ' + esc(b.title) + '">' + ic('play', 'ic-sm') + ' Baca</button>' +
          '<button type="button" class="btn btn-icon btn-sm" data-act="book-log" data-id="' + esc(b.bookId) + '" aria-label="Catat sesi">' + ic('edit', 'ic-sm') + '</button>' +
          '<button type="button" class="btn btn-icon btn-sm" data-act="book-edit" data-id="' + esc(b.bookId) + '" aria-label="Edit buku">' + ic('settings', 'ic-sm') + '</button>' +
          '<button type="button" class="btn btn-icon btn-sm is-danger" data-act="book-del" data-id="' + esc(b.bookId) + '" aria-label="Hapus buku">' + ic('trash', 'ic-sm') + '</button>' +
        '</div></article>';
    }).join('');
    setPage(
      '<div class="page-head"><div><h1>Rak Buku</h1><p>Kelola buku, sampul, dan progres bacaan Anda.</p></div>' +
      '<button type="button" class="btn btn-primary" data-act="book-add">' + ic('plus') + ' Tambah buku</button></div>' +
      '<div class="toolbar"><div class="seg" role="tablist" aria-label="Filter status">' + seg('all', 'Semua', cnt.all) + seg('reading', 'Sedang dibaca', cnt.reading) + seg('done', 'Selesai', cnt.done) + '</div>' +
      '<label class="search"><span class="sr-only">Cari buku</span>' + ic('search') + '<input class="field" id="bookSearch" type="search" placeholder="Cari judul, penulis, atau topik" value="' + esc(S.filter.q) + '">' +
      (S.filter.q ? '<button type="button" class="clear" id="bookSearchClear" aria-label="Hapus pencarian">' + ic('x') + '</button>' : '') + '</label></div>' +
      (list.length ? '<div class="book-grid">' + cards + '</div>' :
        '<div class="empty">' + ic('book') + '<strong>' + (all.length ? 'Tidak ada buku yang cocok' : 'Rak Anda masih kosong') + '</strong><span>' + (all.length ? 'Coba ubah filter atau kata kunci.' : 'Tambahkan buku pertama Anda dan unggah sampulnya.') + '</span>' +
        (all.length ? '' : '<button type="button" class="btn btn-primary" data-act="book-add">' + ic('plus') + ' Tambah buku pertama</button>') + '</div>')
    );
    var inp = $('#bookSearch');
    if (inp) {
      inp.addEventListener('input', debounce(function () { S.filter.q = inp.value.trim(); pageBooks(); $('#bookSearch') && $('#bookSearch').focus(); }, 250));
    }
    var clr = $('#bookSearchClear');
    if (clr) clr.addEventListener('click', function () { S.filter.q = ''; pageBooks(); });
  }

  /* Formulir buku (tambah / edit) dengan unggah sampul ke Google Drive */
  function openBookForm(book) {
    var isNew = !book;
    var topics = uniqueTopics();
    var pendingCover = null, removeCover = false;
    var html =
      '<form id="bookForm" novalidate>' +
        '<div class="form-grid">' +
          '<div class="fg span-2"><label class="lbl" for="bfTitle">Judul buku<span class="req">*</span></label><input class="field" id="bfTitle" name="title" required maxlength="180" value="' + esc(book ? book.title : '') + '" placeholder="Contoh: Atomic Habits"></div>' +
          '<div class="fg"><label class="lbl" for="bfAuthor">Penulis<span class="req">*</span></label><input class="field" id="bfAuthor" name="author" required maxlength="140" value="' + esc(book ? book.author : '') + '" placeholder="Nama penulis"></div>' +
          '<div class="fg"><label class="lbl" for="bfTopic">Topik</label><input class="field" id="bfTopic" name="topic" list="topicList" maxlength="120" value="' + esc(book ? book.topic : 'literasi') + '"><datalist id="topicList">' + topics.map(function (t) { return '<option value="' + esc(t) + '">'; }).join('') + '</datalist></div>' +
          '<div class="fg"><label class="lbl" for="bfTotal">Total halaman<span class="req">*</span></label><input class="field" id="bfTotal" name="totalPages" type="number" inputmode="numeric" min="1" max="50000" required value="' + (book ? book.totalPages : '') + '"></div>' +
          '<div class="fg"><label class="lbl" for="bfCur">Halaman terakhir dibaca</label><input class="field" id="bfCur" name="currentPage" type="number" inputmode="numeric" min="0" value="' + (book ? book.currentPage : 0) + '"><span class="hint">Isi total halaman dengan benar. Jika sama, buku otomatis selesai.</span></div>' +
          '<div class="fg span-2"><span class="lbl">Sampul buku</span>' +
            '<div class="dropzone" id="bfDrop"><input type="file" id="bfFile" accept="image/jpeg,image/png,image/webp" aria-label="Pilih file sampul">' +
              '<div class="dz-prev" id="bfPrev">' + (book && book.coverURL ? '<img src="' + esc(book.coverURL) + '" alt="Sampul saat ini" referrerpolicy="no-referrer">' : ic('image')) + '</div>' +
              '<div class="dz-text"><b id="bfDzTitle">' + (book && book.coverURL ? 'Ganti sampul' : 'Unggah sampul') + '</b><span>JPG, PNG, atau WEBP · otomatis dikecilkan · disimpan di Google Drive</span><span id="bfDzName"></span></div>' +
              '<span class="dz-ic">' + ic('upload') + '</span></div>' +
            (book && book.coverURL ? '<div class="row-wrap" style="margin-top:10px"><button type="button" class="btn btn-danger btn-sm" id="bfCoverDel">' + ic('trash', 'ic-sm') + ' Hapus sampul</button></div>' : '') +
            (isNew ? '<span class="hint">Sampul diunggah setelah buku disimpan.</span>' : '') +
          '</div>' +
        '</div>' +
        '<div class="err-text" id="bfErr" role="alert" style="margin-top:14px"></div>' +
      '</form>';
    var m = openModal({
      title: isNew ? 'Tambah buku baru' : 'Edit buku',
      size: '',
      body: html,
      foot: '<button type="button" class="btn btn-outline" data-md-close>Batal</button><button type="submit" form="bookForm" class="btn btn-primary" id="bfSave">' + ic('check', 'ic-sm') + ' Simpan buku</button>'
    });
    var form = m.body.querySelector('#bookForm');
    var file = m.body.querySelector('#bfFile');
    file.addEventListener('change', function () {
      var f = file.files && file.files[0];
      if (!f) return;
      var err = m.body.querySelector('#bfErr');
      err.textContent = '';
      compressCover(f).then(function (c) {
        pendingCover = c; removeCover = false;
        m.body.querySelector('#bfPrev').innerHTML = '<img src="' + c.previewUrl + '" alt="Pratinjau sampul">';
        m.body.querySelector('#bfDzName').textContent = 'Dipilih: ' + f.name;
        m.body.querySelector('#bfDzTitle').textContent = 'Sampul siap diunggah';
      }).catch(function (e) { err.textContent = errMsg(e); file.value = ''; });
    });
    var del = m.body.querySelector('#bfCoverDel');
    if (del) del.addEventListener('click', function () {
      confirmDialog('Hapus sampul?', 'Sampul akan dihapus dari Google Drive dan tampilan kembali memakai gradien otomatis.', 'Hapus sampul', true).then(function (ok) {
        if (!ok) return;
        setBusy(del, true);
        api('deleteBookCover', { bookId: book.bookId }).then(function (d) {
          toast(d.__m || 'Sampul dihapus.');
          book.coverURL = '';
          return refreshDashboard().then(function () { m.close(); openBookForm(findMyBook(book.bookId)); });
        }).catch(function (e) { toast(errMsg(e), 'error'); setBusy(del, false); });
      });
    });
    form.addEventListener('submit', function (ev) {
      ev.preventDefault();
      var v = { title: form.querySelector('#bfTitle').value.trim(), author: form.querySelector('#bfAuthor').value.trim(), topic: form.querySelector('#bfTopic').value.trim() || 'literasi', totalPages: Number(form.querySelector('#bfTotal').value), currentPage: Number(form.querySelector('#bfCur').value || 0) };
      var err = m.body.querySelector('#bfErr');
      if (v.title.length < 2) return err.textContent = 'Judul buku minimal 2 karakter.';
      if (v.author.length < 2) return err.textContent = 'Nama penulis minimal 2 karakter.';
      if (!(v.totalPages >= 1)) return err.textContent = 'Total halaman harus diisi (minimal 1).';
      if (v.currentPage < 0 || v.currentPage > v.totalPages) return err.textContent = 'Halaman terakhir harus di antara 0 dan total halaman.';
      err.textContent = '';
      var btn = m.el.querySelector('#bfSave');
      setBusy(btn, true);
      var payload = Object.assign({}, v);
      if (book) payload.bookId = book.bookId;
      if (book && book.coverURL && !pendingCover) payload.coverURL = book.coverURL;
      saveBookRequest(payload, book, pendingCover).then(function (savedId) {
        m.close();
        toast(isNew ? 'Buku ditambahkan ke rak.' : 'Perubahan buku disimpan.');
        return refreshDashboard().then(function () { route(); });
      }).catch(function (e) {
        err.textContent = errMsg(e);
        setBusy(btn, false);
      });
    });
  }

  function saveBookRequest(payload, book, pendingCover) {
    return api('saveReadingBook', payload).then(function (d) {
      var bookId = (d.book && d.book.bookId) || (book && book.bookId) || payload.bookId;
      if (!pendingCover) return bookId;
      return api('uploadBookCover', { bookId: bookId, base64: pendingCover.base64, mimeType: pendingCover.mimeType, fileName: pendingCover.fileName })
        .then(function () { return bookId; })
        .catch(function (e) { toast('Buku tersimpan, tetapi sampul gagal diunggah: ' + errMsg(e), 'error'); return bookId; });
    });
  }

  function uniqueTopics() {
    var s = {};
    ((S.dash && S.dash.myBooks) || []).concat((S.dash && S.dash.communityBooks) || []).forEach(function (b) { if (b.topic) s[b.topic] = true; });
    ((S.dash && S.dash.myLogs) || []).forEach(function (l) { if (l.topic) s[l.topic] = true; });
    return Object.keys(s).sort();
  }

  function deleteBook(id) {
    var b = findMyBook(id);
    if (!b) return;
    confirmDialog('Hapus "' + b.title + '"?', 'Buku beserta seluruh catatan bacaan dan sampulnya akan dihapus permanen.', 'Ya, hapus', true).then(function (ok) {
      if (!ok) return;
      api('deleteReadingBook', { bookId: id }).then(function (d) {
        toast(d.__m || 'Buku dihapus.');
        return refreshDashboard().then(route);
      }).catch(function (e) { toast(errMsg(e), 'error'); });
    });
  }

  /* ==========================================================================
   * HALAMAN: DETAIL BUKU & TIMELINE
   * ========================================================================== */
  function pageBookDetail(id) {
    setPage('<div class="skeleton" style="height:260px"></div>');
    api('getBookTimeline', { bookId: id }).then(function (d) {
      if (!d.book) { setPage('<div class="empty">' + ic('book') + '<strong>Buku tidak ditemukan</strong><span>Buku mungkin sudah dihapus atau bersifat privat.</span><button class="btn btn-primary" data-nav="buku">Kembali ke rak</button></div>'); return; }
      var b = d.book, tl = d.timeline || [];
      S.currentTimeline = tl;
      var mine = b.userId === S.user.userId;
      var canEdit = mine || isAdmin();
      var p = pct(b.currentPage, b.totalPages);
      var totalMin = sumBy(tl, 'effectiveMinutes');
      var items = tl.length ? tl.map(function (l, i) { return logItem(l, i, b); }).join('') :
        '<div class="empty">' + ic('notebook') + '<strong>Belum ada catatan</strong><span>Catatan publik dan privat Anda untuk buku ini akan muncul di sini.</span></div>';
      setPage(
        '<div class="page-head"><div><button class="btn btn-ghost btn-sm" data-nav="buku" style="margin-left:-12px">' + ic('arrow-left', 'ic-sm') + ' Kembali ke rak</button><h1 style="margin-top:6px">' + esc(b.title) + '</h1><p>oleh ' + esc(b.author) + ' · dibaca oleh ' + esc(b.readerName) + '</p></div></div>' +
        '<section class="detail-hero reveal">' +
          '<div class="detail-cover">' + coverHTML(b) + '</div>' +
          '<div class="detail-info">' +
            '<div class="row-wrap" style="margin-bottom:12px"><span class="pill">' + esc(b.topic) + '</span>' + (b.status === 'Finished' ? '<span class="pill pill-ok">' + ic('check') + ' Selesai</span>' : '<span class="pill pill-mint">Sedang dibaca</span>') + '</div>' +
            '<div class="bar" style="margin-top:6px"><i data-w="' + p + '"></i></div>' +
            '<div class="spec-grid">' +
              '<div class="spec"><span>Progres</span><b>' + p + '%</b></div>' +
              '<div class="spec"><span>Halaman</span><b>' + fmt(b.currentPage) + ' / ' + fmt(b.totalPages) + '</b></div>' +
              '<div class="spec"><span>Sesi tercatat</span><b>' + fmt(tl.length) + '</b></div>' +
              '<div class="spec"><span>Menit efektif</span><b>' + fmtDur(totalMin) + '</b></div>' +
            '</div>' +
            '<div class="row-wrap" style="margin-top:20px">' +
              '<button type="button" class="btn btn-mint" data-act="book-read" data-id="' + esc(b.bookId) + '">' + ic('play') + ' Baca sekarang</button>' +
              (mine ? '<button type="button" class="btn btn-primary" data-act="book-log" data-id="' + esc(b.bookId) + '">' + ic('edit') + ' Catat sesi</button>' : '') +
              (canEdit ? '<button type="button" class="btn btn-outline" data-act="book-edit" data-id="' + esc(b.bookId) + '">' + ic('settings') + ' Edit</button>' : '') +
              (mine ? '<button type="button" class="btn btn-danger" data-act="book-del" data-id="' + esc(b.bookId) + '">' + ic('trash') + ' Hapus</button>' : '') +
            '</div>' +
          '</div>' +
        '</section>' +
        '<section class="section-head" style="margin-top:28px"><div><h2 class="section-title" style="font-size:22px">Linimasa bacaan</h2><p>' + fmt(tl.length) + ' catatan, dari yang terbaru</p></div></section>' +
        '<div class="tl">' + items + '</div>'
      );
      /* Catatan: id buku dibawa ke formulir lewat data-id pada tombol */
      S.currentBook = b;
    }).catch(function (e) {
      setPage('<div class="empty">' + ic('alert') + '<strong>Gagal memuat buku</strong><span>' + esc(errMsg(e)) + '</span></div>');
    });
  }

  function logItem(l, i, book) {
    var mine = l.userId === S.user.userId;
    var canEdit = mine || isAdmin();
    var comments = (l.comments || []).map(function (c) {
      var canDel = c.userId === S.user.userId || isAdmin();
      return '<div class="cmt">' + avatarHTML({ name: c.userName, avatarURL: c.userAvatar }, 'sm') +
        '<div class="cbox"><div class="row-wrap between"><b>' + esc(c.userName) + '</b>' +
        (canDel ? '<button type="button" class="btn btn-ghost btn-xs" data-act="comment-del" data-id="' + esc(c.commentId) + '" data-log="' + esc(l.logId) + '" aria-label="Hapus komentar">' + ic('x', 'ic-sm') + '</button>' : '') + '</div>' +
        '<p>' + esc(c.commentText) + '</p><small>' + fmtDate(String(c.createdAt).slice(0, 10)) + '</small></div></div>';
    }).join('');
    return '<article class="tl-item" style="--i:' + i + '"><div class="tl-card">' +
      '<div class="tl-head">' + avatarHTML({ name: l.userName, avatarURL: l.userAvatar }, 'sm') + '<b>' + esc(l.userName) + '</b>' +
        '<span class="muted">' + fmtDate(l.date) + '</span>' +
        '<span class="pill">' + fmt(l.startPage) + '–' + fmt(l.endPage) + ' · ' + fmt(l.pagesRead) + ' hal</span>' +
        '<span class="pill pill-mint">' + fmtDur(l.effectiveMinutes) + '</span>' +
        (l.isPublic ? '' : '<span class="pill pill-gray">' + ic('lock', 'ic-sm') + ' Privat</span>') +
        (canEdit ? '<span style="margin-left:auto;display:flex;gap:6px"><button type="button" class="btn btn-icon btn-sm" data-act="log-edit" data-id="' + esc(l.logId) + '" aria-label="Edit catatan">' + ic('edit', 'ic-sm') + '</button>' +
          '<button type="button" class="btn btn-icon btn-sm is-danger" data-act="log-del" data-id="' + esc(l.logId) + '" aria-label="Hapus catatan">' + ic('trash', 'ic-sm') + '</button></span>' : '') +
      '</div>' +
      (l.insight ? '<blockquote>' + esc(l.insight) + '</blockquote>' : '') +
      '<div class="row-wrap small"><span class="topic-chip" style="cursor:default">#' + esc(l.topic) + '</span></div>' +
      '<div class="comments">' + comments + '</div>' +
      '<form class="cmt-form" data-log="' + esc(l.logId) + '" novalidate><label class="sr-only" for="c-' + esc(l.logId) + '">Tulis komentar</label><input class="field" id="c-' + esc(l.logId) + '" name="c" maxlength="800" placeholder="Tulis komentar…"><button class="btn btn-soft btn-sm" type="submit">' + ic('message', 'ic-sm') + ' Kirim</button></form>' +
      '</div></article>';
  }

  /* Kirim komentar lewat delegasi submit pada halaman */
  document.addEventListener('submit', function (ev) {
    var f = ev.target;
    if (!f.classList || !f.classList.contains('cmt-form')) return;
    ev.preventDefault();
    var input = f.querySelector('input[name="c"]');
    var text = input.value.trim();
    if (text.length < 2) { toast('Komentar minimal 2 karakter.', 'error'); return; }
    var btn = f.querySelector('button');
    setBusy(btn, true);
    api('addComment', { logId: f.getAttribute('data-log'), commentText: text }).then(function () {
      toast('Komentar terkirim.');
      return pageBookDetail(S.route.id);
    }).catch(function (e) { toast(errMsg(e), 'error'); setBusy(btn, false); });
  });

  function deleteComment(id, logId) {
    confirmDialog('Hapus komentar?', 'Komentar ini akan dihapus permanen.', 'Hapus', true).then(function (ok) {
      if (!ok) return;
      api('deleteComment', { commentId: id }).then(function () {
        toast('Komentar dihapus.');
        pageBookDetail(S.route.id);
      }).catch(function (e) { toast(errMsg(e), 'error'); });
    });
  }

  function deleteLog(id) {
    confirmDialog('Hapus catatan ini?', 'Catatan dan komentarnya akan dihapus. Progres buku akan dihitung ulang.', 'Ya, hapus', true).then(function (ok) {
      if (!ok) return;
      api('deleteLog', { logId: id }).then(function (d) {
        toast(d.__m || 'Catatan dihapus.');
        return refreshDashboard().then(function () { route(); });
      }).catch(function (e) { toast(errMsg(e), 'error'); });
    });
  }

  /* ==========================================================================
   * HALAMAN: JELAJAH (orang, buku, topik, teman)
   * ========================================================================== */
  function pageExplore() {
    var d = S.dash, tab = S.explore.tab, q = S.explore.q.toLowerCase();
    var tabs = [['orang', 'Orang'], ['buku', 'Buku'], ['topik', 'Topik'], ['teman', 'Teman']];
    var segHTML = '<div class="seg" role="tablist" aria-label="Jelajah">' + tabs.map(function (t) {
      return '<button type="button" role="tab" aria-selected="' + (tab === t[0]) + '" class="' + (tab === t[0] ? 'active' : '') + '" data-act="explore-tab" data-v="' + t[0] + '">' + t[1] + '</button>';
    }).join('') + '</div>';
    var search = '<label class="search"><span class="sr-only">Cari</span>' + ic('search') + '<input class="field" id="exSearch" type="search" placeholder="Cari nama, username, atau judul" value="' + esc(S.explore.q) + '"></label>';
    var body = '';

    if (tab === 'orang' || tab === 'teman') {
      var list = (d.people || []).filter(function (p) {
        if (tab === 'teman' && !p.isFriend) return false;
        return !q || (p.name + ' ' + p.username).toLowerCase().indexOf(q) >= 0;
      });
      body = list.length ? '<div class="people-grid">' + list.map(function (p, i) {
        return '<article class="person reveal" style="--d:' + (i * 40) + 'ms">' + avatarHTML(p, 'lg') +
          '<div class="pinfo"><b>' + esc(p.name) + (p.isMe ? ' <span class="pill pill-gray">Anda</span>' : '') + '</b><span>@' + esc(p.username) + '</span>' +
          '<span>' + fmt(p.booksCount) + ' buku · ' + fmt(p.pagesRead) + ' hal</span></div>' +
          '<div class="pact">' +
          '<button type="button" class="btn btn-outline btn-xs" data-act="shelf" data-id="' + esc(p.userId) + '">' + ic('book', 'ic-sm') + ' Rak</button>' +
          (p.isMe ? '' : '<button type="button" class="btn ' + (p.isFriend ? 'btn-soft' : 'btn-mint') + ' btn-xs" data-act="friend" data-id="' + esc(p.userId) + '" aria-pressed="' + (!!p.isFriend) + '">' + ic(p.isFriend ? 'user-check' : 'user-plus', 'ic-sm') + (p.isFriend ? ' Teman' : ' Ikuti') + '</button>') +
          '</div></article>';
      }).join('') + '</div>' : '<div class="empty">' + ic('users') + '<strong>' + (tab === 'teman' ? 'Belum ada teman' : 'Tidak ada anggota ditemukan') + '</strong><span>' + (tab === 'teman' ? 'Ikuti anggota dari tab Orang untuk melihat aktivitas mereka.' : 'Coba kata kunci lain.') + '</span></div>';
    } else if (tab === 'buku') {
      var books = (d.communityBooks || []).filter(function (b) { return !q || (b.title + ' ' + b.author + ' ' + b.topic).toLowerCase().indexOf(q) >= 0; });
      body = books.length ? '<div class="list-books">' + books.map(function (b, i) {
        return '<div class="list-book reveal" style="--d:' + (i * 40) + 'ms" data-act="book-open" data-id="' + esc(b.bookId) + '" role="button" tabindex="0">' +
          '<div class="lb-cover">' + coverHTML(b) + '</div><div class="lb-info"><b>' + esc(b.title) + '</b><span>' + esc(b.author) + ' · #' + esc(b.topic) + '</span>' +
          '<div class="bar thin" style="margin-top:8px"><i data-w="' + pct(b.currentPage, b.totalPages) + '"></i></div><span>' + esc(b.readerName) + ' · ' + pct(b.currentPage, b.totalPages) + '%</span></div>' + ic('arrow-right', 'ic-sm') + '</div>';
      }).join('') + '</div>' : '<div class="empty">' + ic('book') + '<strong>Belum ada buku</strong><span>Buku anggota komunitas akan tampil di sini.</span></div>';
    } else {
      var counts = {};
      (d.communityBooks || []).forEach(function (b) { counts[b.topic || 'umum'] = (counts[b.topic || 'umum'] || 0) + 1; });
      (d.communityLogs || []).forEach(function (l) { counts[l.topic || 'umum'] = (counts[l.topic || 'umum'] || 0) + 0; });
      var topics = Object.keys(counts).sort(function (a, b) { return counts[b] - counts[a]; });
      var cloud = topics.length ? '<div class="hashtag-cloud">' + topics.map(function (t) {
        return '<button type="button" class="tag-card" data-act="explore-topic" data-v="' + esc(t) + '" aria-pressed="' + (S.explore.topic === t) + '"><b>#' + esc(t) + '</b><span>' + fmt(counts[t]) + ' buku</span></button>';
      }).join('') + '</div>' : '<div class="empty">' + ic('layers') + '<strong>Belum ada topik</strong><span>Topik muncul dari buku yang dibaca anggota.</span></div>';
      var sel = S.explore.topic;
      var selBooks = sel ? (d.communityBooks || []).filter(function (b) { return (b.topic || 'umum') === sel; }) : [];
      body = cloud + (sel ? '<div class="section-head" style="margin-top:24px"><div><h2 class="section-title" style="font-size:20px">Topik #' + esc(sel) + '</h2><p>' + selBooks.length + ' buku</p></div><button class="btn btn-ghost btn-sm" data-act="explore-topic" data-v="">Hapus filter</button></div>' +
        '<div class="list-books">' + selBooks.map(function (b) {
          return '<div class="list-book" data-act="book-open" data-id="' + esc(b.bookId) + '" role="button" tabindex="0"><div class="lb-cover">' + coverHTML(b) + '</div><div class="lb-info"><b>' + esc(b.title) + '</b><span>' + esc(b.author) + ' · ' + esc(b.readerName) + '</span></div></div>';
        }).join('') + '</div>' : '');
    }

    setPage('<div class="page-head"><div><h1>Jelajah</h1><p>Temukan teman baca, buku, dan topik baru.</p></div></div>' +
      '<div class="toolbar">' + segHTML + search + '</div>' + body);
    var si = $('#exSearch');
    if (si) si.addEventListener('input', debounce(function () { S.explore.q = si.value.trim(); pageExplore(); }, 250));
  }

  function toggleFriend(userId, btn) {
    setBusy(btn, true);
    api('toggleFriend', { friendUserId: userId }).then(function (d) {
      var p = (S.dash.people || []).filter(function (x) { return x.userId === userId; })[0];
      if (p) p.isFriend = !!d.isFriend;
      toast(d.__m || (d.isFriend ? 'Berhasil berteman.' : 'Pertemanan dilepas.'));
      pageExplore();
    }).catch(function (e) { toast(errMsg(e), 'error'); setBusy(btn, false); });
  }

  function openShelf(userId) {
    var m = openModal({ title: 'Rak buku', size: 'lg', body: '<div class="skeleton" style="height:200px"></div>', foot: '' });
    api('getUserBookshelf', { userId: userId }).then(function (d) {
      var row = function (b) {
        return '<div class="list-book" data-act="book-open" data-id="' + esc(b.bookId) + '" role="button" tabindex="0" data-close="1"><div class="lb-cover">' + coverHTML(b) + '</div>' +
          '<div class="lb-info"><b>' + esc(b.title) + '</b><span>' + esc(b.author) + ' · ' + pct(b.currentPage, b.totalPages) + '%</span></div></div>';
      };
      m.body.innerHTML = '<div class="profile-hero" style="margin-bottom:18px">' + avatarHTML(d.user, 'lg') + '<div><h2>' + esc(d.user.name) + '</h2><span class="muted">@' + esc(d.user.username) + ' · ' + fmt(d.totalBooks) + ' buku</span></div></div>' +
        '<h3 style="font-size:18px;margin:10px 0">Sedang dibaca</h3>' + (d.readingBooks.length ? '<div class="list-books">' + d.readingBooks.map(row).join('') + '</div>' : '<p class="muted">Tidak ada buku aktif.</p>') +
        '<h3 style="font-size:18px;margin:22px 0 10px">Selesai</h3>' + (d.finishedBooks.length ? '<div class="list-books">' + d.finishedBooks.map(row).join('') + '</div>' : '<p class="muted">Belum ada buku selesai.</p>');
      m.body.addEventListener('click', function (ev) {
        var b = ev.target.closest('[data-close]');
        if (b) { m.close(); go('#/buku/' + encodeURIComponent(b.getAttribute('data-id'))); }
      });
    }).catch(function (e) { m.body.innerHTML = '<p class="err-text">' + esc(errMsg(e)) + '</p>'; });
  }

  /* ==========================================================================
   FORMULIR CATATAN BACA (manual & dari timer) — stepper halaman & menit
   ========================================================================== */
  function stepperHTML(id, label, value, steps, min, max) {
    var btns = steps.map(function (s) {
      return '<button type="button" class="btn btn-soft btn-xs" data-t="' + id + '" data-by="' + s + '" data-min="' + min + '" data-max="' + max + '">' + (s > 0 ? '+' + s : s) + '</button>';
    }).join('');
    return '<div class="fg"><label class="lbl" for="' + id + '">' + esc(label) + '</label>' +
      '<div class="input-group" style="align-items:stretch">' +
        '<button type="button" class="btn btn-icon" data-t="' + id + '" data-by="-1" data-min="' + min + '" data-max="' + max + '" aria-label="Kurangi ' + esc(label) + '">' + ic('minus') + '</button>' +
        '<input class="field" id="' + id + '" type="number" inputmode="numeric" min="' + min + '" max="' + max + '" value="' + value + '" style="text-align:center;font-family:var(--font-head);font-weight:800;font-size:20px">' +
        '<button type="button" class="btn btn-icon" data-t="' + id + '" data-by="1" data-min="' + min + '" data-max="' + max + '" aria-label="Tambah ' + esc(label) + '">' + ic('plus') + '</button>' +
      '</div><div class="row-wrap" style="margin-top:8px;gap:6px">' + btns + '</div></div>';
  }

  function openLogForm(opts) {
    opts = opts || {};
    var log = opts.log || null, timer = opts.timer || null, book = opts.book || null;
    var mine = (S.dash.myBooks || []);
    var reading = mine.slice().sort(function (a, b) { return String(b.updatedAt || '').localeCompare(String(a.updatedAt || '')); });
    var preBook = null;
    if (log) preBook = mine.filter(function (b) { return b.bookId === log.bookId; })[0] || null;
    else if (book && mine.some(function (b) { return b.bookId === book.bookId; })) preBook = book;
    else if (timer && timer.bookId) preBook = mine.filter(function (b) { return b.bookId === timer.bookId; })[0] || null;
    else if (!timer && !book) preBook = reading.filter(function (b) { return b.status !== 'Finished'; })[0] || null;

    var v = {
      date: log ? log.date : todayKey(),
      startPage: log ? log.startPage : (timer ? timer.startPage : (preBook ? Math.min(preBook.totalPages, preBook.currentPage + 1) : 1)),
      endPage: log ? log.endPage : (timer ? timer.startPage : (preBook ? Math.min(preBook.totalPages, preBook.currentPage + 1) : 1)),
      totalMinutes: log ? log.totalMinutes : (timer ? timer.totalMinutes : 30),
      effectiveMinutes: log ? log.effectiveMinutes : (timer ? timer.effectiveMinutes : 30),
      insight: log ? log.insight : '',
      topic: log ? log.topic : (timer && timer.topic) || (preBook ? preBook.topic : 'literasi'),
      isPublic: log ? !!log.isPublic : true,
      bookTitle: log ? log.bookTitle : (timer ? timer.title : (book && !preBook ? book.title : '')),
      author: log ? log.author : (timer ? timer.author : (book && !preBook ? book.author : '')),
      totalBookPages: log ? log.totalBookPages : (timer ? timer.totalPages : (book && !preBook ? book.totalPages : (preBook ? preBook.totalPages : 200)))
    };
    var useNew = !preBook;
    var bookOpts = reading.map(function (b) {
      return '<option value="' + esc(b.bookId) + '"' + (preBook && preBook.bookId === b.bookId ? ' selected' : '') + '>' + esc(b.title) + (b.status === 'Finished' ? ' (selesai)' : '') + '</option>';
    }).join('');
    var html =
      '<form id="logForm" novalidate>' +
        '<div class="form-grid">' +
          '<div class="fg span-2"><label class="lbl" for="lgBook">Buku<span class="req">*</span></label>' +
            '<select class="field" id="lgBook" name="bookId"><option value="__new__"' + (useNew ? ' selected' : '') + '>+ Buku lain / belum ada di rak</option>' + bookOpts + '</select></div>' +
          '<div class="fg span-2" id="lgNewBox" ' + (useNew ? '' : 'hidden') + '>' +
            '<div class="form-grid" style="gap:14px">' +
              '<div class="fg"><label class="lbl" for="lgTitle">Judul buku<span class="req">*</span></label><input class="field" id="lgTitle" maxlength="180" value="' + esc(v.bookTitle) + '"></div>' +
              '<div class="fg"><label class="lbl" for="lgAuthor">Penulis<span class="req">*</span></label><input class="field" id="lgAuthor" maxlength="140" value="' + esc(v.author) + '"></div>' +
              '<div class="fg"><label class="lbl" for="lgTotalBook">Total halaman buku</label><input class="field" id="lgTotalBook" type="number" inputmode="numeric" min="1" value="' + v.totalBookPages + '"></div>' +
            '</div></div>' +
          '<div class="fg"><label class="lbl" for="lgDate">Tanggal baca</label><input class="field" id="lgDate" type="date" value="' + esc(v.date) + '" max="' + todayKey() + '"></div>' +
          '<div class="fg"><label class="lbl" for="lgTopic">Topik</label><input class="field" id="lgTopic" list="lgTopicList" maxlength="120" value="' + esc(v.topic) + '"><datalist id="lgTopicList">' + uniqueTopics().map(function (t) { return '<option value="' + esc(t) + '">'; }).join('') + '</datalist></div>' +
          stepperHTML('lgStart', 'Halaman mulai', v.startPage, [-10, -1, 1, 10], 1, 50000) +
          stepperHTML('lgEnd', 'Halaman selesai', v.endPage, [-10, -1, 1, 10], 1, 50000) +
          stepperHTML('lgMin', 'Durasi total (menit)', v.totalMinutes, [-15, -5, 5, 15], 1, 1440) +
          stepperHTML('lgEff', 'Menit efektif (tanpa jeda)', v.effectiveMinutes, [-5, -1, 1, 5], 0, 1440) +
          '<div class="fg span-2"><div class="prog-live"><div class="row-wrap between"><span id="lgPagesInfo" style="font-weight:700">Halaman dibaca: 1</span><span class="muted small" id="lgEffInfo"></span></div><div class="bar" style="margin-top:10px"><i id="lgBar" data-w="0"></i></div></div></div>' +
          '<div class="fg span-2"><label class="lbl" for="lgInsight">Kesimpulan / insight<span class="req">*</span></label><textarea class="field" id="lgInsight" maxlength="3000" placeholder="Apa yang paling berkesan dari bacaan ini?">' + esc(v.insight) + '</textarea><span class="hint" id="lgInsightCount">' + v.insight.length + ' / 3000 karakter (minimal 3)</span></div>' +
          '<div class="fg span-2"><label class="switch"><input type="checkbox" id="lgPublic" ' + (v.isPublic ? 'checked' : '') + '><span class="track" aria-hidden="true"></span><span>Tampilkan catatan ini ke komunitas</span></label><span class="hint">Catatan privat hanya terlihat oleh Anda.</span></div>' +
        '</div>' +
        '<div class="err-text" id="lgErr" role="alert" style="margin-top:14px"></div>' +
      '</form>';
    var editing = !!log;
    var m = openModal({
      title: editing ? 'Edit catatan bacaan' : (timer ? 'Simpan hasil membaca' : 'Catat sesi membaca'),
      size: 'lg',
      body: html,
      dismissible: !timer,
      onClose: function () { if (timer && S.timer) clearTimerState(); },
      foot: '<button type="button" class="btn btn-outline" data-md-close>' + (timer ? 'Buang sesi' : 'Batal') + '</button><button type="submit" form="logForm" class="btn btn-primary" id="lgSave">' + ic('check', 'ic-sm') + ' Simpan catatan</button>',
    });
    var body = m.body, form = body.querySelector('#logForm');
    var sel = body.querySelector('#lgBook');

    function val(id) { return Number(body.querySelector('#' + id).value); }
    function sync() {
      var s = val('lgStart'), e = val('lgEnd'), tm = val('lgMin'), ef = val('lgEff');
      if (e < s) { /* biarkan, validasi saat simpan */ }
      var pages = Math.max(0, e - s + 1);
      body.querySelector('#lgPagesInfo').textContent = 'Halaman dibaca: ' + fmt(pages);
      body.querySelector('#lgEffInfo').textContent = ef > tm ? 'Menit efektif tidak boleh melebihi durasi total' : (tm ? 'Efektif ' + pct(ef, tm) + '% dari durasi total' : '');
      var tot = Number(body.querySelector('#lgTotalBook') ? body.querySelector('#lgTotalBook').value : (preBook ? preBook.totalPages : v.totalBookPages)) || 1;
      body.querySelector('#lgBar').setAttribute('data-w', String(pct(e, tot)));
      body.querySelector('#lgBar').style.width = pct(e, tot) + '%';
      body.querySelector('#lgInsightCount').textContent = body.querySelector('#lgInsight').value.length + ' / 3000 karakter (minimal 3)';
    }
    body.addEventListener('click', function (ev) {
      var b = ev.target.closest('[data-t][data-by]');
      if (!b) return;
      var input = body.querySelector('#' + b.getAttribute('data-t'));
      var by = Number(b.getAttribute('data-by')), mn = Number(b.getAttribute('data-min')), mx = Number(b.getAttribute('data-max'));
      input.value = String(Math.min(mx, Math.max(mn, (Number(input.value) || 0) + by)));
      sync();
    });
    body.addEventListener('input', sync);
    sel.addEventListener('change', function () {
      var isNew = sel.value === '__new__';
      body.querySelector('#lgNewBox').hidden = !isNew;
      if (!isNew) {
        var b = mine.filter(function (x) { return x.bookId === sel.value; })[0];
        if (b) {
          body.querySelector('#lgTopic').value = b.topic || 'literasi';
          body.querySelector('#lgStart').value = String(Math.min(b.totalPages, b.currentPage + 1));
          body.querySelector('#lgEnd').value = String(Math.min(b.totalPages, b.currentPage + 1));
        }
      }
      sync();
    });
    sync();

    form.addEventListener('submit', function (ev) {
      ev.preventDefault();
      var err = body.querySelector('#lgErr');
      var isNew = sel.value === '__new__';
      var payload = {
        date: body.querySelector('#lgDate').value || todayKey(),
        topic: body.querySelector('#lgTopic').value.trim() || 'literasi',
        startPage: val('lgStart'), endPage: val('lgEnd'),
        totalMinutes: val('lgMin'), effectiveMinutes: val('lgEff'),
        insight: body.querySelector('#lgInsight').value.trim(),
        isPublic: body.querySelector('#lgPublic').checked
      };
      if (!isNew) payload.bookId = sel.value;
      else {
        payload.bookTitle = body.querySelector('#lgTitle').value.trim();
        payload.author = body.querySelector('#lgAuthor').value.trim();
        payload.totalBookPages = Number(body.querySelector('#lgTotalBook').value) || payload.endPage;
        if (payload.bookTitle.length < 2) return err.textContent = 'Judul buku wajib diisi.';
        if (payload.author.length < 2) return err.textContent = 'Nama penulis wajib diisi.';
      }
      if (!(payload.startPage >= 1)) return err.textContent = 'Halaman mulai minimal 1.';
      if (payload.endPage < payload.startPage) return err.textContent = 'Halaman selesai tidak boleh sebelum halaman mulai.';
      if (!(payload.totalMinutes >= 1)) return err.textContent = 'Durasi total minimal 1 menit.';
      if (payload.effectiveMinutes < 0 || payload.effectiveMinutes > payload.totalMinutes) return err.textContent = 'Menit efektif harus di antara 0 dan durasi total.';
      if (payload.insight.length < 3) return err.textContent = 'Kesimpulan / insight minimal 3 karakter.';
      if (payload.date > todayKey()) return err.textContent = 'Tanggal baca tidak boleh di masa depan.';
      if (log) payload.logId = log.logId;
      if (timer) { payload.startTime = timer.startTime; payload.endTime = timer.endTime; }
      err.textContent = '';
      var btn = m.el.querySelector('#lgSave');
      setBusy(btn, true);
      api('saveLog', payload).then(function (d) {
        m.close();
        if (timer) clearTimerState();
        toast(d.__m || 'Catatan tersimpan.');
        return refreshDashboard().then(function () { route(); });
      }).catch(function (e) { err.textContent = errMsg(e); setBusy(btn, false); });
    });
  }

  /* ==========================================================================
   * SMART READING TIMER — fullscreen, jeda/lanjut, auto-isi catatan
   * ========================================================================== */
  function timerElapsed(t) { return t.acc + (t.running ? Date.now() - t.resumedAt : 0); }
  function saveTimerState() {
    try { if (S.timer) localStorage.setItem(TIMER_KEY, JSON.stringify(S.timer)); } catch (e) { /* abaikan */ }
  }
  function clearTimerState() {
    S.timer = null;
    try { localStorage.removeItem(TIMER_KEY); } catch (e) { /* abaikan */ }
    stopTick();
    hideTimerUI();
  }
  function hms(ms) {
    var s = Math.floor(ms / 1000), h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), sec = s % 60;
    return (h ? String(h).padStart(2, '0') + ':' : '') + String(m).padStart(2, '0') + ':' + String(sec).padStart(2, '0');
  }

  function openTimerSetup(book) {
    if (S.timer) { showTimerOverlay(); return; }
    var reading = (S.dash.myBooks || []).filter(function (b) { return b.status !== 'Finished'; });
    var pre = book ? (reading.some(function (b) { return b.bookId === book.bookId; }) ? book.bookId : '__other__') : (reading.length ? reading[0].bookId : '__other__');
    var opts = reading.map(function (b) { return '<option value="' + esc(b.bookId) + '"' + (pre === b.bookId ? ' selected' : '') + '>' + esc(b.title) + '</option>'; }).join('');
    var m = openModal({
      title: 'Mulai Smart Reading Timer',
      size: 'sm',
      body:
        '<form id="tsForm" novalidate>' +
          '<p class="muted" style="margin-bottom:16px">Timer berjalan fullscreen. Jeda kapan saja. Saat selesai, menit efektif otomatis masuk ke catatan.</p>' +
          '<div class="fg" style="margin-bottom:16px"><label class="lbl" for="tsBook">Buku yang dibaca</label><select class="field" id="tsBook">' + opts + '<option value="__other__"' + (pre === '__other__' ? ' selected' : '') + '>Buku lain (ketik judul)</option></select></div>' +
          '<div id="tsOther" ' + (pre === '__other__' ? '' : 'hidden') + '>' +
            '<div class="fg" style="margin-bottom:16px"><label class="lbl" for="tsTitle">Judul buku<span class="req">*</span></label><input class="field" id="tsTitle" maxlength="180" value="' + esc(book && pre === '__other__' ? book.title : '') + '"></div>' +
            '<div class="fg" style="margin-bottom:16px"><label class="lbl" for="tsAuthor">Penulis<span class="req">*</span></label><input class="field" id="tsAuthor" maxlength="140" value="' + esc(book && pre === '__other__' ? book.author : '') + '"></div>' +
            '<div class="fg" style="margin-bottom:16px"><label class="lbl" for="tsTotal">Total halaman buku</label><input class="field" id="tsTotal" type="number" inputmode="numeric" min="1" value="' + (book && pre === '__other__' ? book.totalPages : 200) + '"></div>' +
          '</div>' +
          '<div class="fg"><label class="lbl" for="tsStart">Mulai dari halaman</label><input class="field" id="tsStart" type="number" inputmode="numeric" min="1" value="' + (function () { var b = reading.filter(function (x) { return x.bookId === pre; })[0]; return b ? Math.min(b.totalPages, b.currentPage + 1) : 1; })() + '"></div>' +
          '<div class="err-text" id="tsErr" role="alert" style="margin-top:12px"></div>' +
        '</form>',
      foot: '<button type="submit" form="tsForm" class="btn btn-mint btn-block" id="tsGo">' + ic('play') + ' Mulai timer</button>'
    });
    var f = m.body.querySelector('#tsForm'), sel = m.body.querySelector('#tsBook');
    sel.addEventListener('change', function () { m.body.querySelector('#tsOther').hidden = sel.value !== '__other__'; });
    f.addEventListener('submit', function (ev) {
      ev.preventDefault();
      var err = m.body.querySelector('#tsErr');
      var info = { bookId: '', title: '', author: '', totalPages: 200, startPage: Math.max(1, Number(f.querySelector('#tsStart').value) || 1), topic: '' };
      if (sel.value === '__other__') {
        info.title = f.querySelector('#tsTitle').value.trim();
        info.author = f.querySelector('#tsAuthor').value.trim();
        info.totalPages = Math.max(1, Number(f.querySelector('#tsTotal').value) || 200);
        if (info.title.length < 2) return err.textContent = 'Judul buku wajib diisi.';
        if (info.author.length < 2) return err.textContent = 'Nama penulis wajib diisi.';
      } else {
        var b = reading.filter(function (x) { return x.bookId === sel.value; })[0];
        if (!b) return err.textContent = 'Pilih buku terlebih dahulu.';
        info.bookId = b.bookId; info.title = b.title; info.author = b.author; info.totalPages = b.totalPages; info.topic = b.topic;
      }
      m.close();
      startTimer(info);
    });
  }

  function startTimer(info) {
    var now = Date.now();
    S.timer = Object.assign({}, info, { startedAt: now, acc: 0, running: true, resumedAt: now });
    saveTimerState();
    showTimerOverlay();
    startTick();
    toast('Timer dimulai. Selamat membaca!');
  }

  function restoreTimerIfAny() {
    try {
      var raw = localStorage.getItem(TIMER_KEY);
      if (raw && !S.timer) S.timer = JSON.parse(raw);
    } catch (e) { S.timer = null; }
    if (S.timer) { startTick(); renderPill(); }
  }

  function startTick() {
    stopTick();
    S.timerTick = setInterval(paintTimer, 500);
    paintTimer();
  }
  function stopTick() { if (S.timerTick) { clearInterval(S.timerTick); S.timerTick = null; } }

  function paintTimer() {
    var t = S.timer;
    if (!t) { stopTick(); return; }
    var el = timerElapsed(t);
    $$('[data-clock]').forEach(function (n) { n.textContent = hms(el); });
    $$('[data-pill-time]').forEach(function (n) { n.textContent = hms(el); });
    $$('[data-clock]').forEach(function (n) { n.classList.toggle('paused', !t.running); });
    var st = $('[data-timer-state]');
    if (st) st.textContent = t.running ? 'Sedang membaca' : 'Dijeda';
    // Auto-simpan setiap ~15 detik agar tidak hilang saat tab ditutup
    if (!t._lastSave || Date.now() - t._lastSave > 15000) { t._lastSave = Date.now(); saveTimerState(); }
  }

  function showTimerOverlay() {
    var t = S.timer;
    if (!t) return;
    var old = document.getElementById('timerPill');
    if (old) old.remove();
    var root = $('#timerRoot');
    root.innerHTML =
      '<div class="timer-overlay" role="dialog" aria-modal="true" aria-label="Smart Reading Timer">' +
        '<button type="button" class="t-close" data-tm="min" aria-label="Kecilkan timer">' + ic('x') + '</button>' +
        '<div class="timer-cover">' + coverHTML({ title: t.title, author: t.author, coverURL: t.coverURL || '' }) + '</div>' +
        '<h2>' + esc(t.title) + '</h2><p class="t-author">' + esc(t.author) + '</p>' +
        '<div class="timer-status" data-timer-state>' + (t.running ? 'Sedang membaca' : 'Dijeda') + '</div>' +
        '<div class="clock' + (t.running ? '' : ' paused') + '" data-clock aria-live="off">' + hms(timerElapsed(t)) + '</div>' +
        '<div class="t-info">' +
          '<div><span>Halaman mulai</span><b>' + fmt(t.startPage) + '</b></div>' +
          '<div><span>Total buku</span><b>' + fmt(t.totalPages) + ' hal</b></div>' +
          '<div><span>Mulai pukul</span><b>' + fmtTime(new Date(t.startedAt).toISOString()) + '</b></div>' +
        '</div>' +
        '<div class="t-controls">' +
          '<div style="position:relative"><button type="button" class="t-btn cancel" data-tm="cancel" aria-label="Batalkan sesi">' + ic('trash') + '</button><span class="lbl-sm">Batal</span></div>' +
          '<div style="position:relative"><button type="button" class="t-btn pause' + (t.running ? ' is-run' : '') + '" data-tm="toggle" aria-label="' + (t.running ? 'Jeda' : 'Lanjutkan') + '">' + ic(t.running ? 'pause' : 'play') + '</button><span class="lbl-sm">' + (t.running ? 'Jeda' : 'Lanjut') + '</span></div>' +
          '<div style="position:relative"><button type="button" class="t-btn finish" data-tm="finish" aria-label="Selesai dan simpan catatan">' + ic('check') + '</button><span class="lbl-sm">Selesai</span></div>' +
        '</div>' +
      '</div>';
    hydrateIcons(root);
    root.querySelector('.timer-overlay').addEventListener('click', onTimerClick);
    var first = root.querySelector('[data-tm="toggle"]');
    if (first) setTimeout(function () { first.focus({ preventScroll: true }); }, 60);
    startTick();
  }

  function renderPill(hidden) {
    var root = $('#timerRoot');
    var overlay = root && root.querySelector('.timer-overlay');
    if (overlay) return; // overlay sedang tampil; pill disembunyikan
    if (!S.timer || hidden) { var old = $('#timerPill'); if (old) old.remove(); return; }
    var t = S.timer;
    var pill = document.getElementById('timerPill');
    if (!pill) {
      pill = document.createElement('button');
      pill.type = 'button';
      pill.id = 'timerPill';
      pill.className = 'timer-pill';
      pill.addEventListener('click', function () { showTimerOverlay(); });
      document.body.appendChild(pill);
    }
    pill.innerHTML = '<span class="tp-time" data-pill-time>' + hms(timerElapsed(t)) + '</span><span class="tp-title truncate">' + esc(t.title) + '</span><span class="tp-go" aria-hidden="true">' + ic('play', 'ic-sm') + '</span>';
    pill.setAttribute('aria-label', 'Buka timer baca: ' + t.title);
  }

  function hideTimerUI() {
    var root = $('#timerRoot');
    if (root) root.innerHTML = '';
    var pill = document.getElementById('timerPill');
    if (pill) pill.remove();
  }

  function minimizeTimer() {
    var root = $('#timerRoot');
    if (root) root.innerHTML = '';
    renderPill();
    toast('Timer dikecilkan. Ketuk pil di bawah untuk kembali.', 'info');
  }

  function onTimerClick(ev) {
    var b = ev.target.closest('[data-tm]');
    if (!b || !S.timer) return;
    var act = b.getAttribute('data-tm');
    var t = S.timer;
    if (act === 'min') return minimizeTimer();
    if (act === 'toggle') {
      if (t.running) { t.acc += Date.now() - t.resumedAt; t.running = false; }
      else { t.resumedAt = Date.now(); t.running = true; }
      saveTimerState();
      var root = $('#timerRoot');
      root.innerHTML = '';
      showTimerOverlay();
      return;
    }
    if (act === 'cancel') {
      if (timerElapsed(t) < 5000) { clearTimerState(); toast('Sesi dibatalkan.', 'info'); return; }
      confirmDialog('Batalkan sesi?', 'Waktu membaca yang sudah berjalan tidak akan disimpan.', 'Ya, batalkan', true).then(function (ok) {
        if (ok) { clearTimerState(); toast('Sesi dibatalkan.', 'info'); }
      });
      return;
    }
    if (act === 'finish') return finishTimer();
  }

  function finishTimer() {
    var t = S.timer;
    if (!t) return;
    var now = Date.now();
    var active = timerElapsed(t);
    var total = now - t.startedAt;
    var totalMin = Math.max(1, Math.round(total / 60000));
    var effMin = Math.min(totalMin, Math.max(0, Math.round(active / 60000)));
    var data = {
      bookId: t.bookId, title: t.title, author: t.author, totalPages: t.totalPages, startPage: t.startPage,
      topic: t.topic || '', totalMinutes: totalMin, effectiveMinutes: effMin,
      startTime: new Date(t.startedAt).toISOString(), endTime: new Date(now).toISOString()
    };
    stopTick();
    var root = $('#timerRoot');
    if (root) root.innerHTML = '';
    var pill = document.getElementById('timerPill');
    if (pill) pill.remove();
    openLogForm({ timer: data });
    toast('Sesi selesai: ' + effMin + ' menit efektif. Lengkapi catatan Anda.', 'info');
    // Jika catatan dibatalkan, timer tetap dianggap selesai (dibuang) — dialog dismissible=false
  }

  /* ==========================================================================
   * HALAMAN: KELAS
   * ========================================================================== */
  function pageClasses() {
    var d = S.dash;
    var classes = (d.classes || []).slice().sort(function (a, b) {
      return (b.joined - a.joined) || (a.status === 'Closed') - (b.status === 'Closed') || String(b.startDate).localeCompare(String(a.startDate));
    });
    var cards = classes.map(function (c, i) {
      var alumni = c.classType === 'Alumni';
      var canJoin = !c.joined && c.status === 'Active' && !alumni;
      return '<article class="class-card reveal' + (c.joined ? ' joined' : '') + '" style="--d:' + (i * 80) + 'ms">' +
        '<div class="row-wrap between"><span class="pill ' + (alumni ? 'pill-gold' : 'pill-mint') + '">' + (alumni ? 'Kelas Alumni' : 'Batch ' + (c.batchNumber || '')) + '</span>' +
        (c.status === 'Closed' ? '<span class="pill pill-gray">Ditutup</span>' : (c.joined ? '<span class="pill pill-ok">' + ic('check') + ' Anda bergabung</span>' : '')) + '</div>' +
        '<div><h3>' + esc(c.className) + '</h3>' + (c.description ? '<p class="cdesc clamp-3" style="margin-top:6px">' + esc(c.description) + '</p>' : '') + '</div>' +
        '<div class="class-meta">' +
          '<div>Mentor<b>' + esc(c.mentorName) + '</b></div>' +
          '<div>Periode<b>' + fmtDate(c.startDate, false) + ' – ' + fmtDate(c.endDate) + '</b></div>' +
          '<div>Anggota<b>' + fmt(c.membersCount) + '</b></div>' +
          '<div>Target<b>' + fmt(c.targetPagesPerDay) + ' hal/hari</b></div>' +
        '</div>' +
        '<p class="small muted">Syarat lulus: minimal ' + c.minGradTasks + ' tugas dan ' + fmt(c.minGradPages) + ' halaman.</p>' +
        '<div class="class-actions">' +
          (canJoin ? '<button type="button" class="btn btn-primary btn-sm" data-act="class-join" data-id="' + esc(c.classId) + '">' + ic('user-plus', 'ic-sm') + ' Gabung kelas</button>' : '') +
          (c.joined ? '<button type="button" class="btn btn-soft btn-sm" data-act="class-board" data-id="' + esc(c.classId) + '">' + ic('trophy', 'ic-sm') + ' Peringkat</button><button type="button" class="btn btn-outline btn-sm" data-go-tasks="1">' + ic('task', 'ic-sm') + ' Tugas</button>' : '') +
          '<button type="button" class="btn btn-ghost btn-sm" data-act="class-members" data-id="' + esc(c.classId) + '">' + ic('users', 'ic-sm') + ' Anggota</button>' +
          (isAdmin() ? '<button type="button" class="btn btn-icon btn-sm" data-act="class-edit" data-id="' + esc(c.classId) + '" aria-label="Edit kelas">' + ic('settings', 'ic-sm') + '</button>' +
            (alumni ? '' : '<button type="button" class="btn btn-gold btn-sm" data-act="class-gen" data-id="' + esc(c.classId) + '">' + ic('layers', 'ic-sm') + ' Buat 10 tugas</button>') +
            '<button type="button" class="btn btn-icon btn-sm is-danger" data-act="class-del" data-id="' + esc(c.classId) + '" aria-label="Hapus kelas">' + ic('trash', 'ic-sm') + '</button>' : '') +
        '</div></article>';
    }).join('');
    setPage('<div class="page-head"><div><h1>Kelas Pendampingan</h1><p>Batch 30 hari dengan 10 tugas, mentor, dan papan peringkat.</p></div>' +
      (isAdmin() ? '<button type="button" class="btn btn-primary" data-act="class-add">' + ic('plus') + ' Buat kelas</button>' : '') + '</div>' +
      (classes.length ? '<div class="grid-2">' + cards + '</div>' : '<div class="empty">' + ic('class') + '<strong>Belum ada kelas</strong><span>' + (isAdmin() ? 'Buat kelas batch pertama Anda.' : 'Kelas baru akan tampil di sini.') + '</span></div>'));
    $$('[data-go-tasks]').forEach(function (b) { b.addEventListener('click', function () { go('#/tugas'); }); });
  }

  function classForm(c) {
    var html =
      '<form id="clsForm" novalidate><div class="form-grid">' +
        '<div class="fg span-2"><label class="lbl" for="cfName">Nama kelas<span class="req">*</span></label><input class="field" id="cfName" maxlength="140" value="' + esc(c ? c.className : '') + '" placeholder="Contoh: Kelas Membaca Batch 5"></div>' +
        '<div class="fg"><label class="lbl" for="cfType">Jenis</label><select class="field" id="cfType"><option value="Batch"' + (!c || c.classType !== 'Alumni' ? ' selected' : '') + '>Batch</option><option value="Alumni"' + (c && c.classType === 'Alumni' ? ' selected' : '') + '>Alumni</option></select></div>' +
        '<div class="fg"><label class="lbl" for="cfBatch">Nomor batch</label><input class="field" id="cfBatch" type="number" min="0" value="' + (c ? c.batchNumber : '') + '"></div>' +
        '<div class="fg"><label class="lbl" for="cfMentor">Mentor</label><input class="field" id="cfMentor" maxlength="100" value="' + esc(c ? c.mentorName : '') + '"></div>' +
        '<div class="fg"><label class="lbl" for="cfStatus">Status</label><select class="field" id="cfStatus"><option value="Active"' + (!c || c.status !== 'Closed' ? ' selected' : '') + '>Aktif (dibuka)</option><option value="Closed"' + (c && c.status === 'Closed' ? ' selected' : '') + '>Ditutup</option></select></div>' +
        '<div class="fg"><label class="lbl" for="cfStart">Tanggal mulai</label><input class="field" id="cfStart" type="date" value="' + esc(c ? c.startDate : '') + '"></div>' +
        '<div class="fg"><label class="lbl" for="cfEnd">Tanggal berakhir</label><input class="field" id="cfEnd" type="date" value="' + esc(c ? c.endDate : '') + '"></div>' +
        '<div class="fg"><label class="lbl" for="cfClose">Batas simpan data</label><input class="field" id="cfClose" type="date" value="' + esc(c ? c.closeDate : '') + '"></div>' +
        '<div class="fg"><label class="lbl" for="cfTarget">Target halaman per hari</label><input class="field" id="cfTarget" type="number" min="1" value="' + (c ? c.targetPagesPerDay : CFG.TARGET_PAGES) + '"></div>' +
        '<div class="fg"><label class="lbl" for="cfGradT">Minimal tugas lulus</label><input class="field" id="cfGradT" type="number" min="0" max="10" value="' + (c ? c.minGradTasks : 6) + '"></div>' +
        '<div class="fg"><label class="lbl" for="cfGradP">Minimal halaman lulus</label><input class="field" id="cfGradP" type="number" min="0" value="' + (c ? c.minGradPages : 1000) + '"></div>' +
        '<div class="fg span-2"><label class="lbl" for="cfDesc">Deskripsi</label><textarea class="field" id="cfDesc" maxlength="2000">' + esc(c ? c.description : '') + '</textarea></div>' +
      '</div><div class="err-text" id="cfErr" role="alert" style="margin-top:12px"></div></form>';
    return html;
  }

  function openClassForm(c) {
    var m = openModal({
      title: c ? 'Edit kelas' : 'Buat kelas baru', size: 'lg', body: classForm(c),
      foot: '<button type="button" class="btn btn-outline" data-md-close>Batal</button><button type="submit" form="clsForm" class="btn btn-primary" id="cfSave">' + ic('check', 'ic-sm') + ' Simpan kelas</button>'
    });
    var f = m.body.querySelector('#clsForm');
    f.addEventListener('submit', function (ev) {
      ev.preventDefault();
      var err = m.body.querySelector('#cfErr');
      var payload = {
        className: f.querySelector('#cfName').value.trim(),
        classType: f.querySelector('#cfType').value,
        batchNumber: Number(f.querySelector('#cfBatch').value) || 0,
        mentorName: f.querySelector('#cfMentor').value.trim(),
        status: f.querySelector('#cfStatus').value,
        startDate: f.querySelector('#cfStart').value,
        endDate: f.querySelector('#cfEnd').value,
        closeDate: f.querySelector('#cfClose').value,
        targetPagesPerDay: Number(f.querySelector('#cfTarget').value) || CFG.TARGET_PAGES,
        minGradTasks: Number(f.querySelector('#cfGradT').value),
        minGradPages: Number(f.querySelector('#cfGradP').value),
        description: f.querySelector('#cfDesc').value.trim()
      };
      if (payload.className.length < 3) return err.textContent = 'Nama kelas minimal 3 karakter.';
      if (payload.startDate && payload.endDate && payload.endDate < payload.startDate) return err.textContent = 'Tanggal berakhir tidak boleh sebelum tanggal mulai.';
      if (c) payload.classId = c.classId;
      err.textContent = '';
      var btn = m.el.querySelector('#cfSave');
      setBusy(btn, true);
      api('saveClass', payload).then(function (d) {
        m.close();
        toast(d.__m || 'Kelas tersimpan.');
        return refreshDashboard().then(route);
      }).catch(function (e) { err.textContent = errMsg(e); setBusy(btn, false); });
    });
  }

  function joinClass(id, btn) {
    setBusy(btn, true);
    api('joinClass', { classId: id }).then(function (d) {
      toast(d.__m || 'Berhasil bergabung ke kelas.');
      return refreshDashboard().then(route);
    }).catch(function (e) { toast(errMsg(e), 'error'); setBusy(btn, false); });
  }

  function deleteClass(id) {
    var c = findClass(id);
    confirmDialog('Hapus kelas?', 'Kelas "' + (c ? c.className : '') + '" beserta tugas terkaitnya akan dihapus permanen.', 'Ya, hapus', true).then(function (ok) {
      if (!ok) return;
      api('deleteClass', { classId: id }).then(function (d) {
        toast(d.__m || 'Kelas dihapus.');
        return refreshDashboard().then(route);
      }).catch(function (e) { toast(errMsg(e), 'error'); });
    });
  }

  function generateTasks(id, btn) {
    confirmDialog('Buat 10 tugas otomatis?', 'Tugas standar akan ditambahkan ke kelas ini. Tugas yang sudah ada tidak diubah.', 'Buat tugas', false).then(function (ok) {
      if (!ok) return;
      setBusy(btn, true);
      api('generateClassTasks', { classId: id }).then(function (d) {
        toast(d.__m || 'Tugas kelas dibuat.');
        return refreshDashboard().then(route);
      }).catch(function (e) { toast(errMsg(e), 'error'); setBusy(btn, false); });
    });
  }

  function openClassMembers(id) {
    var c = findClass(id);
    var m = openModal({ title: 'Anggota ' + (c ? c.className : 'kelas'), size: 'lg', body: '<div class="skeleton" style="height:180px"></div>', foot: '' });
    api('listClassMembers', { classId: id }).then(function (d) {
      var rows = (d.members || []).map(function (p) {
        return '<div class="mrow">' + avatarHTML(p, 'sm') + '<div class="mi"><b>' + esc(p.name) + '</b><span>@' + esc(p.username) + ' · bergabung ' + fmtDate(p.enrollmentDate) + '</span></div>' +
          '<div class="ma"><span class="pill">' + fmt(p.pagesRead) + ' hal</span><span class="pill pill-mint">' + fmtDur(p.effectiveMinutes) + '</span><span class="pill ' + (p.graduationStatus === 'Graduated' ? 'pill-ok' : 'pill-gray') + '">' + (p.graduationStatus === 'Graduated' ? 'Lulus' : 'Berjalan') + '</span></div></div>';
      }).join('');
      m.body.innerHTML = '<p class="muted" style="margin-bottom:14px">' + fmt(d.members.length) + ' anggota · ' + esc(d.classItem.mentorName) + '</p>' +
        (rows ? '<div style="display:flex;flex-direction:column;gap:10px">' + rows + '</div>' : '<div class="empty">' + ic('users') + '<strong>Belum ada anggota</strong></div>');
      hydrateIcons(m.body);
    }).catch(function (e) { m.body.innerHTML = '<p class="err-text">' + esc(errMsg(e)) + '</p>'; });
  }

  /* ==========================================================================
   * HALAMAN: TUGAS (10 tugas terjadwal, form dinamis, penilaian admin)
   * ========================================================================== */
  var STATUS_LABEL = { Submitted: 'Terkirim', Reviewed: 'Dinilai', Draft: 'Draf', Published: 'Dipublikasi', Closed: 'Ditutup' };

  function pageTasks() {
    var d = S.dash, today = todayKey();
    var tasks = (d.tasks || []).slice();
    if (S.tasksClass) tasks = tasks.filter(function (t) { return t.classId === S.tasksClass; });
    tasks.sort(function (a, b) { return (a.activeDate || '').localeCompare(b.activeDate || '') || a.taskNumber - b.taskNumber; });
    var groups = { active: [], upcoming: [], past: [] };
    tasks.forEach(function (t) {
      if (t.activeDate === today) groups.active.push(t);
      else if (t.activeDate > today) groups.upcoming.push(t);
      else groups.past.push(t);
    });
    var classFilter = (d.classes || []).length > 1 ? '<label class="search" style="max-width:300px;min-width:200px"><span class="sr-only">Filter kelas</span><select class="field" id="taskClassSel" style="padding-left:16px;border-radius:999px">' +
      '<option value="">Semua kelas</option>' + (d.classes || []).map(function (c) { return '<option value="' + esc(c.classId) + '"' + (S.tasksClass === c.classId ? ' selected' : '') + '>' + esc(c.className) + '</option>'; }).join('') + '</select></label>' : '';
    var section = function (title, desc, arr, cls) {
      if (!arr.length) return '';
      return '<section class="reveal" style="margin-top:22px"><div class="section-head"><div><h2 class="section-title" style="font-size:20px">' + title + '</h2><p>' + desc + '</p></div></div>' +
        '<div class="grid-2">' + arr.map(function (t, i) { return taskCard(t, cls, i); }).join('') + '</div></section>';
    };
    var empty = !tasks.length ? '<div class="empty" style="margin-top:20px">' + ic('task') + '<strong>Belum ada tugas</strong><span>' + (isAdmin() ? 'Buat tugas baru atau generate 10 tugas untuk kelas batch.' : 'Tugas akan muncul setelah Anda bergabung dengan kelas.') + '</span>' +
      (isAdmin() ? '<button class="btn btn-primary" data-act="task-add">' + ic('plus') + ' Tugas baru</button>' : '') + '</div>' : '';
    setPage('<div class="page-head"><div><h1>Tugas Kelas</h1><p>Kerjakan tugas pada tanggal aktifnya (00.00–24.00 WIB).</p></div>' +
      '<div class="row-wrap">' + classFilter + (isAdmin() ? '<button type="button" class="btn btn-primary" data-act="task-add">' + ic('plus') + ' Tugas baru</button>' : '') + '</div></div>' +
      empty +
      section('Hari ini', 'Tugas yang aktif sekarang', groups.active, 'is-active') +
      section('Akan datang', 'Tugas yang belum aktif', groups.upcoming, '') +
      section('Sebelumnya', 'Riwayat tugas', groups.past, 'is-exp'));
    var sel = $('#taskClassSel');
    if (sel) sel.addEventListener('change', function () { S.tasksClass = sel.value; pageTasks(); });
  }

  function taskCard(t, cls, i) {
    var today = todayKey();
    var isActiveDay = t.activeDate === today;
    var sub = t.submission;
    var canDo = (isActiveDay || isAdmin()) && t.status !== 'Closed' && t.status !== 'Draft';
    var status = sub ? (STATUS_LABEL[sub.status] || sub.status) : '';
    var rule = t.validationRule && t.validationRule.type === 'reading_pages' ? '<span class="pill pill-gold">Min. ' + fmt(t.validationRule.minPages) + ' halaman</span>' : '';
    return '<article class="task-card reveal ' + cls + '" style="--d:' + (i * 60) + 'ms">' +
      '<div class="task-head"><div class="task-no">' + (t.taskNumber || '') + '</div><div style="min-width:0"><h3>' + esc(t.title) + '</h3>' +
      '<div class="small muted">' + esc(t.className || 'Kelas') + ' · ' + fmtDate(t.activeDate) + '</div></div></div>' +
      (t.description ? '<p class="clamp-3" style="color:var(--ink-2)">' + esc(t.description) + '</p>' : '') +
      '<div class="row-wrap">' + (sub ? '<span class="pill ' + (sub.status === 'Reviewed' ? 'pill-ok' : 'pill-mint') + '">' + ic('check', 'ic-sm') + ' ' + esc(status) + '</span>' : '<span class="pill pill-gray">Belum dikerjakan</span>') + rule +
        (isAdmin() ? '<span class="pill pill-gray">' + esc(STATUS_LABEL[t.status] || t.status) + '</span><span class="pill pill-gray">' + fmt(t.submissionCount) + ' pengumpulan</span>' : '') + '</div>' +
      (sub && (sub.score !== null || sub.feedback) ? '<div class="task-fb">' + (sub.score !== null ? '<b>Skor: ' + esc(sub.score) + '</b>' : '') + (sub.feedback ? '<div style="margin-top:4px">' + esc(sub.feedback) + '</div>' : '') + '</div>' : '') +
      '<div class="task-actions">' +
        (canDo ? '<button type="button" class="btn ' + (sub ? 'btn-soft' : 'btn-primary') + ' btn-sm" data-act="task-submit" data-id="' + esc(t.taskId) + '">' + ic(sub ? 'edit' : 'arrow-right', 'ic-sm') + ' ' + (sub ? 'Ubah jawaban' : 'Kerjakan') + '</button>' :
          (!isActiveDay && !isAdmin() && t.activeDate > today ? '<span class="pill pill-gray">' + ic('calendar', 'ic-sm') + ' Dibuka ' + fmtDate(t.activeDate) + '</span>' : '<span class="pill pill-gray">Ditutup</span>')) +
        (isAdmin() ? '<button type="button" class="btn btn-outline btn-sm" data-act="task-subs" data-id="' + esc(t.taskId) + '">' + ic('users', 'ic-sm') + ' Pengumpulan</button>' +
          '<button type="button" class="btn btn-icon btn-sm" data-act="task-edit" data-id="' + esc(t.taskId) + '" aria-label="Edit tugas">' + ic('settings', 'ic-sm') + '</button>' +
          '<button type="button" class="btn btn-icon btn-sm is-danger" data-act="task-del" data-id="' + esc(t.taskId) + '" aria-label="Hapus tugas">' + ic('trash', 'ic-sm') + '</button>' : '') +
      '</div></article>';
  }

  /* Render satu field form dinamis (dipakai pengerjaan tugas) */
  function renderField(f, value) {
    var id = 'af_' + f.id, req = f.required ? ' required' : '';
    var lbl = '<label class="lbl" for="' + id + '">' + esc(f.label) + (f.required ? '<span class="req">*</span>' : '') + '</label>';
    var ph = f.placeholder ? ' placeholder="' + esc(f.placeholder) + '"' : '';
    var opts = f.options || [];
    if (f.type === 'textarea') return '<div class="fg span-2">' + lbl + '<textarea class="field" id="' + id + '" name="' + esc(f.id) + '" data-type="textarea"' + req + ph + ' maxlength="4000">' + esc(value || '') + '</textarea></div>';
    if (f.type === 'select') return '<div class="fg span-2">' + lbl + '<select class="field" id="' + id + '" name="' + esc(f.id) + '" data-type="select"' + req + '><option value="">Pilih…</option>' + opts.map(function (o) { return '<option' + (value === o ? ' selected' : '') + '>' + esc(o) + '</option>'; }).join('') + '</select></div>';
    if (f.type === 'radio') return '<fieldset class="fg span-2" style="border:0;padding:0;margin:0"><legend class="lbl">' + esc(f.label) + (f.required ? '<span class="req">*</span>' : '') + '</legend><div style="display:flex;flex-direction:column;gap:8px">' + opts.map(function (o, i) {
      return '<label class="check-row"><input type="radio" name="' + esc(f.id) + '" value="' + esc(o) + '" data-type="radio" data-req="' + (f.required ? 1 : 0) + '"' + (value === o ? ' checked' : '') + '><span>' + esc(o) + '</span></label>';
    }).join('') + '</div></fieldset>';
    if (f.type === 'checkbox') {
      var arr = Array.isArray(value) ? value : [];
      return '<fieldset class="fg span-2" style="border:0;padding:0;margin:0"><legend class="lbl">' + esc(f.label) + (f.required ? '<span class="req">*</span>' : '') + '</legend><div style="display:flex;flex-direction:column;gap:8px">' + opts.map(function (o) {
        return '<label class="check-row"><input type="checkbox" name="' + esc(f.id) + '" value="' + esc(o) + '" data-type="checkbox" data-req="' + (f.required ? 1 : 0) + '"' + (arr.indexOf(o) >= 0 ? ' checked' : '') + '><span>' + esc(o) + '</span></label>';
      }).join('') + '</div></fieldset>';
    }
    var type = { number: 'number', url: 'url', date: 'date' }[f.type] || 'text';
    return '<div class="fg span-2">' + lbl + '<input class="field" id="' + id + '" name="' + esc(f.id) + '" type="' + type + '" data-type="' + esc(f.type) + '"' + req + ph + (type === 'number' ? ' inputmode="decimal"' : '') + ' value="' + esc(value === undefined || value === null ? '' : value) + '"></div>';
  }

  function openSubmitForm(task) {
    if (!task) return;
    var sub = task.submission || null;
    var form = Array.isArray(task.form) ? task.form : [];
    var answers = sub && sub.answers ? sub.answers : {};
    var body = form.length ? form.map(function (f) { return renderField(f, answers[f.id]); }).join('') :
      '<p class="muted">Tugas ini belum memiliki pertanyaan. Tekan kirim untuk mencatat penyelesaian.</p>';
    var m = openModal({
      title: task.title,
      size: 'lg',
      body: '<p class="muted" style="margin-bottom:16px">' + esc(task.description || 'Lengkapi semua field bertanda * sebelum mengirim.') + '</p>' +
        '<form id="subForm" novalidate><div class="form-grid">' + body + '</div><div class="err-text" id="subErr" role="alert" style="margin-top:14px"></div></form>',
      foot: '<button type="button" class="btn btn-outline" data-md-close>Batal</button><button type="submit" form="subForm" class="btn btn-primary" id="subSave">' + ic('check', 'ic-sm') + ' Kirim jawaban</button>'
    });
    var f = m.body.querySelector('#subForm');
    f.addEventListener('submit', function (ev) {
      ev.preventDefault();
      var err = m.body.querySelector('#subErr');
      var out = {}, bad = '';
      form.forEach(function (fd) {
        if (bad) return;
        var val;
        if (fd.type === 'checkbox') {
          val = $$('input[name="' + fd.id + '"]:checked', f).map(function (x) { return x.value; });
          if (fd.required && !val.length) bad = fd.label + ' wajib dipilih minimal satu.';
        } else if (fd.type === 'radio') {
          var r = f.querySelector('input[name="' + fd.id + '"]:checked');
          val = r ? r.value : '';
          if (fd.required && !val) bad = fd.label + ' wajib dipilih.';
        } else {
          var el = f.querySelector('[name="' + fd.id + '"]');
          val = el ? String(el.value || '').trim() : '';
          if (fd.required && !val) bad = fd.label + ' wajib diisi.';
          if (!bad && fd.type === 'url' && val && !/^https?:\/\//i.test(val)) bad = fd.label + ' harus diawali http:// atau https://';
          if (!bad && fd.type === 'number' && val !== '' && !isFinite(Number(val))) bad = fd.label + ' harus berupa angka.';
        }
        out[fd.id] = val;
      });
      if (bad) { err.textContent = bad; return; }
      err.textContent = '';
      var btn = m.el.querySelector('#subSave');
      setBusy(btn, true);
      api('submitTask', { taskId: task.taskId, answers: out }).then(function (d) {
        m.close();
        toast(d.__m || 'Jawaban terkirim.');
        return refreshDashboard().then(route);
      }).catch(function (e) { err.textContent = errMsg(e); setBusy(btn, false); });
    });
  }

  function openTaskForm(t) {
    var classes = S.dash.classes || [];
    var fields = (t && Array.isArray(t.form) ? t.form : []).map(function (x) { return Object.assign({}, x, { options: (x.options || []).slice() }); });
    var rule = t && t.validationRule ? t.validationRule : {};
    var hasRule = rule.type === 'reading_pages';
    var html =
      '<form id="tkForm" novalidate><div class="form-grid">' +
        '<div class="fg span-2"><label class="lbl" for="tkTitle">Judul tugas<span class="req">*</span></label><input class="field" id="tkTitle" maxlength="180" value="' + esc(t ? t.title : '') + '"></div>' +
        '<div class="fg"><label class="lbl" for="tkClass">Kelas<span class="req">*</span></label><select class="field" id="tkClass">' + classes.map(function (c) { return '<option value="' + esc(c.classId) + '"' + (t && t.classId === c.classId ? ' selected' : '') + '>' + esc(c.className) + '</option>'; }).join('') + '</select></div>' +
        '<div class="fg"><label class="lbl" for="tkNo">Nomor tugas (1–99)</label><input class="field" id="tkNo" type="number" min="1" max="99" value="' + (t ? t.taskNumber : 1) + '"></div>' +
        '<div class="fg"><label class="lbl" for="tkDate">Tanggal aktif</label><input class="field" id="tkDate" type="date" value="' + esc(t ? t.activeDate : todayKey()) + '"></div>' +
        '<div class="fg"><label class="lbl" for="tkStatus">Status</label><select class="field" id="tkStatus">' + ['Draft', 'Published', 'Closed'].map(function (s) { return '<option' + (t && t.status === s ? ' selected' : (!t && s === 'Published' ? ' selected' : '')) + '>' + s + '</option>'; }).join('') + '</select></div>' +
        '<div class="fg span-2"><label class="lbl" for="tkDesc">Deskripsi / instruksi</label><textarea class="field" id="tkDesc" maxlength="3000">' + esc(t ? t.description : '') + '</textarea></div>' +
        '<div class="fg span-2"><label class="switch"><input type="checkbox" id="tkRule" ' + (hasRule ? 'checked' : '') + '><span class="track" aria-hidden="true"></span><span>Wajib membaca minimal halaman tertentu</span></label></div>' +
        '<div class="fg" id="tkMinBox" ' + (hasRule ? '' : 'hidden') + '><label class="lbl" for="tkMin">Minimal halaman</label><input class="field" id="tkMin" type="number" min="0" value="' + (rule.minPages || 35) + '"></div>' +
      '</div>' +
      '<div style="margin-top:22px"><div class="row-wrap between" style="margin-bottom:12px"><div><h3 style="font-size:18px">Form pengisian</h3><p class="small muted">Atur pertanyaan yang akan diisi peserta.</p></div>' +
        '<button type="button" class="btn btn-soft btn-sm" id="tkAddField">' + ic('plus', 'ic-sm') + ' Tambah field</button></div>' +
        '<div id="tkFields" style="display:flex;flex-direction:column;gap:12px"></div></div>' +
      '<div class="err-text" id="tkErr" role="alert" style="margin-top:14px"></div></form>';
    var m = openModal({
      title: t ? 'Edit tugas' : 'Tugas baru', size: 'lg', body: html,
      foot: '<button type="button" class="btn btn-outline" data-md-close>Batal</button><button type="submit" form="tkForm" class="btn btn-primary" id="tkSave">' + ic('check', 'ic-sm') + ' Simpan tugas</button>'
    });
    var f = m.body.querySelector('#tkForm');
    var TYPES = [['text', 'Teks singkat'], ['textarea', 'Paragraf'], ['number', 'Angka'], ['url', 'Tautan (URL)'], ['date', 'Tanggal'], ['select', 'Pilihan dropdown'], ['radio', 'Pilihan tunggal'], ['checkbox', 'Pilihan ganda']];

    function readFields() {
      $$('.tk-field', m.body).forEach(function (row, i) {
        var fd = fields[i];
        if (!fd) return;
        fd.label = row.querySelector('.tk-label').value.trim();
        fd.type = row.querySelector('.tk-type').value;
        fd.required = row.querySelector('.tk-req').checked;
        fd.placeholder = row.querySelector('.tk-ph') ? row.querySelector('.tk-ph').value.trim() : '';
        var o = row.querySelector('.tk-opts');
        fd.options = o ? o.value.split(',').map(function (x) { return x.trim(); }).filter(Boolean) : [];
      });
    }
    function drawFields() {
      var box = m.body.querySelector('#tkFields');
      if (!fields.length) { box.innerHTML = '<div class="empty" style="padding:22px">' + ic('list-ordered') + '<span>Belum ada field. Tambahkan pertanyaan untuk peserta.</span></div>'; return; }
      box.innerHTML = fields.map(function (fd, i) {
        var needsOpts = ['select', 'radio', 'checkbox'].indexOf(fd.type) >= 0;
        return '<div class="tk-field card" style="padding:16px;box-shadow:none">' +
          '<div class="form-grid" style="gap:12px">' +
            '<div class="fg"><label class="lbl">Label pertanyaan</label><input class="field tk-label" maxlength="140" value="' + esc(fd.label) + '"></div>' +
            '<div class="fg"><label class="lbl">Jenis input</label><select class="field tk-type">' + TYPES.map(function (x) { return '<option value="' + x[0] + '"' + (fd.type === x[0] ? ' selected' : '') + '>' + x[1] + '</option>'; }).join('') + '</select></div>' +
            (needsOpts ? '<div class="fg span-2"><label class="lbl">Opsi (pisahkan dengan koma)</label><input class="field tk-opts" value="' + esc((fd.options || []).join(', ')) + '" placeholder="Contoh: Fiksi, Nonfiksi, Lainnya"></div>' : '') +
            '<div class="fg span-2"><label class="lbl">Teks bantuan (opsional)</label><input class="field tk-ph" maxlength="160" value="' + esc(fd.placeholder || '') + '"></div>' +
          '</div>' +
          '<div class="row-wrap between" style="margin-top:12px"><label class="check-row" style="padding:8px 12px"><input type="checkbox" class="tk-req" ' + (fd.required ? 'checked' : '') + '><span>Wajib diisi</span></label>' +
          '<div class="row-wrap" style="gap:6px"><button type="button" class="btn btn-icon btn-sm" data-mv="up" data-i="' + i + '" aria-label="Naikkan field"' + (i === 0 ? ' disabled' : '') + '>' + ic('chevron-up', 'ic-sm') + '</button>' +
          '<button type="button" class="btn btn-icon btn-sm" data-mv="down" data-i="' + i + '" aria-label="Turunkan field"' + (i === fields.length - 1 ? ' disabled' : '') + '>' + ic('chevron-down', 'ic-sm') + '</button>' +
          '<button type="button" class="btn btn-icon btn-sm is-danger" data-mv="del" data-i="' + i + '" aria-label="Hapus field">' + ic('trash', 'ic-sm') + '</button></div></div></div>';
      }).join('');
      hydrateIcons(box);
    }
    drawFields();
    m.body.querySelector('#tkAddField').addEventListener('click', function () {
      if (fields.length >= 35) { toast('Maksimal 35 field.', 'error'); return; }
      readFields();
      fields.push({ id: 'field_' + (fields.length + 1) + '_' + Math.random().toString(36).slice(2, 5), label: '', type: 'text', required: false, options: [], placeholder: '' });
      drawFields();
    });
    m.body.addEventListener('click', function (ev) {
      var b = ev.target.closest('[data-mv]');
      if (!b) return;
      readFields();
      var i = Number(b.getAttribute('data-i')), act = b.getAttribute('data-mv');
      if (act === 'del') fields.splice(i, 1);
      if (act === 'up' && i > 0) { var a = fields[i]; fields[i] = fields[i - 1]; fields[i - 1] = a; }
      if (act === 'down' && i < fields.length - 1) { var c = fields[i]; fields[i] = fields[i + 1]; fields[i + 1] = c; }
      drawFields();
    });
    m.body.querySelector('#tkRule').addEventListener('change', function () { m.body.querySelector('#tkMinBox').hidden = !this.checked; });
    m.body.addEventListener('change', function (ev) { if (ev.target.classList.contains('tk-type')) { readFields(); drawFields(); } });

    f.addEventListener('submit', function (ev) {
      ev.preventDefault();
      readFields();
      var err = m.body.querySelector('#tkErr');
      var title = f.querySelector('#tkTitle').value.trim();
      if (title.length < 3) return err.textContent = 'Judul tugas minimal 3 karakter.';
      for (var i = 0; i < fields.length; i++) {
        if (!fields[i].label) return err.textContent = 'Semua field harus memiliki label.';
        if (['select', 'radio', 'checkbox'].indexOf(fields[i].type) >= 0 && (fields[i].options || []).length < 2) return err.textContent = 'Field "' + fields[i].label + '" membutuhkan minimal 2 opsi.';
      }
      var payload = {
        classId: f.querySelector('#tkClass').value,
        title: title,
        taskNumber: Number(f.querySelector('#tkNo').value) || 1,
        activeDate: f.querySelector('#tkDate').value,
        status: f.querySelector('#tkStatus').value,
        description: f.querySelector('#tkDesc').value.trim(),
        form: fields.map(function (x, idx) {
          return { id: x.id || ('field_' + (idx + 1)), label: x.label, type: x.type, required: !!x.required, options: x.options || [], placeholder: x.placeholder || '' };
        }),
        validationRule: f.querySelector('#tkRule').checked ? { type: 'reading_pages', minPages: Number(f.querySelector('#tkMin').value) || 0 } : {}
      };
      if (!payload.classId) return err.textContent = 'Pilih kelas untuk tugas ini.';
      if (t) payload.taskId = t.taskId;
      err.textContent = '';
      var btn = m.el.querySelector('#tkSave');
      setBusy(btn, true);
      api('saveTask', payload).then(function (d) {
        m.close();
        toast(d.__m || 'Tugas tersimpan.');
        return refreshDashboard().then(route);
      }).catch(function (e) { err.textContent = errMsg(e); setBusy(btn, false); });
    });
  }

  function deleteTask(id) {
    confirmDialog('Hapus tugas?', 'Tugas dan seluruh pengumpulan peserta akan dihapus permanen.', 'Ya, hapus', true).then(function (ok) {
      if (!ok) return;
      api('deleteTask', { taskId: id }).then(function (d) {
        toast(d.__m || 'Tugas dihapus.');
        return refreshDashboard().then(route);
      }).catch(function (e) { toast(errMsg(e), 'error'); });
    });
  }

  function openSubmissions(task) {
    if (!task) return;
    var m = openModal({ title: 'Pengumpulan: ' + task.title, size: 'lg', body: '<div class="skeleton" style="height:180px"></div>', foot: '' });
    api('listTaskSubmissions', { taskId: task.taskId }).then(function (d) {
      var subs = d.submissions || [];
      var labelOf = {};
      (task.form || []).forEach(function (f) { labelOf[f.id] = f; });
      if (!subs.length) { m.body.innerHTML = '<div class="empty">' + ic('users') + '<strong>Belum ada pengumpulan</strong></div>'; return; }
      m.body.innerHTML = subs.map(function (s) {
        var ans = Object.keys(s.answers || {}).map(function (k) {
          var v = s.answers[k];
          var lbl = labelOf[k] ? labelOf[k].label : k;
          return '<div style="margin-bottom:8px"><span class="small muted">' + esc(lbl) + '</span><div style="overflow-wrap:anywhere">' + esc(Array.isArray(v) ? v.join(', ') : v) + '</div></div>';
        }).join('') || '<span class="muted">Tidak ada jawaban.</span>';
        return '<form class="card sub-form" data-ut="' + esc(s.userTaskId) + '" style="margin-bottom:14px;box-shadow:none" novalidate>' +
          '<div class="row-wrap between" style="margin-bottom:10px"><b style="font-family:var(--font-head);font-size:17px">' + esc(s.memberName) + '</b><span class="small muted">' + fmtDate(String(s.submittedAt).slice(0, 10)) + ' · ' + (STATUS_LABEL[s.status] || esc(s.status)) + '</span></div>' +
          '<div style="background:var(--surface-2);border-radius:14px;padding:14px;margin-bottom:12px">' + ans + '</div>' +
          '<div class="form-grid" style="gap:12px"><div class="fg"><label class="lbl">Skor (0–100)</label><input class="field" name="score" type="number" min="0" max="100" value="' + (s.score === null ? '' : s.score) + '"></div>' +
          '<div class="fg"><label class="lbl">Feedback</label><input class="field" name="feedback" maxlength="2000" value="' + esc(s.feedback) + '"></div></div>' +
          '<div class="row-wrap" style="justify-content:flex-end;margin-top:10px"><button class="btn btn-primary btn-sm" type="submit">' + ic('check', 'ic-sm') + ' Simpan penilaian</button></div></form>';
      }).join('');
      hydrateIcons(m.body);
      m.body.addEventListener('submit', function (ev) {
        var f = ev.target.closest('.sub-form');
        if (!f) return;
        ev.preventDefault();
        var btn = f.querySelector('button[type="submit"]');
        setBusy(btn, true);
        api('reviewSubmission', { userTaskId: f.getAttribute('data-ut'), score: f.querySelector("[name=score]").value, feedback: f.querySelector("[name=feedback]").value.trim() }).then(function (r) {
          toast(r.__m || 'Penilaian tersimpan.');
          setBusy(btn, false);
        }).catch(function (e) { toast(errMsg(e), 'error'); setBusy(btn, false); });
      });
    }).catch(function (e) { m.body.innerHTML = '<p class="err-text">' + esc(errMsg(e)) + '</p>'; });
  }

  /* ==========================================================================
   * HALAMAN: PERINGKAT
   * ========================================================================== */
  function pageLeaderboard() {
    var d = S.dash;
    var classes = (d.classes || []).slice().sort(function (a, b) { return (b.joined - a.joined); });
    if (S.lbClass === undefined || S.lbClass === null) S.lbClass = '';
    if (!S.lbClass && classes.some(function (c) { return c.joined; })) { /* default: komunitas */ }
    var days = S.lbDays || 30;
    var segDays = [7, 30, 90].map(function (n) {
      return '<button type="button" role="tab" aria-selected="' + (days === n) + '" class="' + (days === n ? 'active' : '') + '" data-act="lb-days" data-v="' + n + '">' + n + ' hari</button>';
    }).join('');
    var opts = '<option value="">Komunitas (semua)</option>' + classes.map(function (c) {
      return '<option value="' + esc(c.classId) + '"' + (S.lbClass === c.classId ? ' selected' : '') + '>' + esc(c.className) + (c.joined ? ' ✓' : '') + '</option>';
    }).join('');
    setPage('<div class="page-head"><div><h1>Papan Peringkat</h1><p>Peringkat berdasarkan halaman yang dibaca dan tugas yang selesai.</p></div></div>' +
      '<div class="toolbar"><label class="search" style="max-width:360px;min-width:220px"><span class="sr-only">Pilih kelas</span><select class="field" id="lbSel" style="padding-left:16px;border-radius:999px">' + opts + '</select></label>' +
      '<div class="seg" role="tablist" aria-label="Rentang waktu">' + segDays + '</div></div><div id="lbBody"><div class="skeleton" style="height:240px"></div></div>');
    var sel = $('#lbSel');
    sel.addEventListener('change', function () { S.lbClass = sel.value; pageLeaderboard(); });
    api('leaderboard', { classId: S.lbClass || '', days: days }).then(function (r) {
      var rows = r.leaderboard || [];
      var me = S.user.userId;
      var top = rows.slice(0, 3);
      var podium = top.length ? '<div class="grid-2 reveal" style="grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin-bottom:20px">' + top.map(function (p, i) {
        var medal = ['#F59E0B', '#98A2B3', '#B45309'][i];
        return '<div class="card" style="text-align:center;border-top:5px solid ' + medal + ';padding:24px 18px;animation:viewIn .5s var(--ease) both;animation-delay:' + (i * 120) + 'ms">' +
          '<div style="font-family:var(--font-head);font-weight:800;font-size:30px;color:' + medal + '">#' + (i + 1) + '</div>' +
          '<div style="display:flex;justify-content:center;margin:12px 0">' + avatarHTML(p, 'lg') + '</div>' +
          '<b style="font-family:var(--font-head);font-size:18px;display:block">' + esc(p.name) + (p.userId === me ? ' (Anda)' : '') + '</b>' +
          '<span class="small muted">@' + esc(p.username) + '</span>' +
          '<div style="font-family:var(--font-head);font-weight:800;font-size:24px;margin-top:10px">' + fmt(p.pagesRead) + ' <span class="small muted">halaman</span></div>' +
          '<div class="small muted">' + fmt(p.tasksDone) + ' tugas · ' + fmtDur(p.effectiveMinutes) + '</div></div>';
      }).join('') + '</div>' : '';
      var list = rows.slice(3).map(function (p, i) {
        return '<div class="lb-row' + (p.userId === me ? '' : '') + '" style="--i:' + i + '">' +
          '<div class="rk">' + p.rank + '</div>' + avatarHTML(p, 'sm') +
          '<div class="lbi"><b>' + esc(p.name) + (p.userId === me ? ' <span class="pill pill-mint">Anda</span>' : '') + '</b><span>@' + esc(p.username) + '</span></div>' +
          '<div class="lb-stats"><div><b>' + fmt(p.pagesRead) + '</b><span>hal</span></div><div><b>' + fmt(p.tasksDone) + '</b><span>tugas</span></div><div><b>' + fmtDur(p.effectiveMinutes) + '</b><span>waktu</span></div></div></div>';
      }).join('');
      var body = rows.length ? podium + (list ? '<div style="display:flex;flex-direction:column;gap:10px">' + list + '</div>' : '') :
        '<div class="empty">' + ic('trophy') + '<strong>Belum ada data peringkat</strong><span>Mulai membaca dan catat sesi Anda untuk masuk ke papan peringkat.</span></div>';
      $('#lbBody').innerHTML = '<div class="view">' + body + '</div>';
      observeReveals($('#lbBody'));
    }).catch(function (e) {
      $('#lbBody').innerHTML = '<div class="empty">' + ic('alert') + '<strong>Peringkat belum dapat dimuat</strong><span>' + esc(errMsg(e)) + '</span></div>';
    });
  }

  /* ==========================================================================
   * HALAMAN: PROFIL
   * ========================================================================== */
  function pageProfile() {
    var u = S.user, d = S.dash;
    var me = (d.people || []).filter(function (p) { return p.isMe; })[0] || {};
    setPage(
      '<div class="page-head"><div><h1>Profil Saya</h1><p>Kelola identitas, keamanan akun, dan pengaturan.</p></div></div>' +
      '<section class="card card-lg reveal"><div class="profile-hero">' + avatarHTML(u, 'xl') + '<div style="min-width:0"><h2>' + esc(u.name) + '</h2>' +
        '<div class="row-wrap" style="margin-top:6px"><span class="pill">@' + esc(u.username) + '</span><span class="pill ' + (isAdmin() ? 'pill-gold' : 'pill-mint') + '">' + (isAdmin() ? 'Admin' : 'Member') + '</span>' +
        (u.joinDate ? '<span class="small muted">Bergabung ' + fmtDate(u.joinDate) + '</span>' : '') + '</div>' +
        (u.bio ? '<p style="margin-top:10px;color:var(--ink-2)">' + esc(u.bio) + '</p>' : '') + '</div></div>' +
        '<div class="kpi-grid" style="margin-top:20px">' +
          '<div class="kpi-card"><span class="k-lbl">Buku</span><span class="kpi">' + fmt(me.booksCount || 0) + '</span></div>' +
          '<div class="kpi-card mint"><span class="k-lbl">Catatan</span><span class="kpi">' + fmt(me.logsCount || 0) + '</span></div>' +
          '<div class="kpi-card pink"><span class="k-lbl">Halaman</span><span class="kpi">' + fmt(me.pagesRead || 0) + '</span></div>' +
          '<div class="kpi-card gold"><span class="k-lbl">Tugas selesai</span><span class="kpi">' + fmt((d.userTasks || []).length) + '</span></div></div></section>' +
      '<div class="grid-2" style="margin-top:18px">' +
        '<section class="card card-lg reveal" aria-labelledby="pfEdit"><h2 id="pfEdit" style="font-size:20px;margin-bottom:16px">Informasi profil</h2>' +
          '<form id="pfForm" novalidate><div class="form-grid" style="gap:14px">' +
            '<div class="fg"><label class="lbl" for="pfName">Nama</label><input class="field" id="pfName" maxlength="100" value="' + esc(u.name) + '"></div>' +
            '<div class="fg"><label class="lbl" for="pfUser">Username</label><input class="field" id="pfUser" maxlength="40" value="' + esc(u.username) + '"></div>' +
            '<div class="fg span-2"><label class="lbl" for="pfAvatar">Tautan foto profil <span class="muted small">(opsional)</span></label><input class="field" id="pfAvatar" type="url" value="' + esc(u.avatarURL || '') + '" placeholder="https://…"></div>' +
            '<div class="fg span-2"><label class="lbl" for="pfBio">Bio</label><textarea class="field" id="pfBio" maxlength="400">' + esc(u.bio || '') + '</textarea></div>' +
            '<div class="fg span-2"><label class="lbl" for="pfWa">Pengaturan pengingat (opsional)</label><input class="field" id="pfWa" maxlength="200" value="' + esc(u.waSettings || '') + '" placeholder="Contoh: pengingat 20.00 WIB"></div>' +
          '</div><div class="err-text" id="pfErr" role="alert" style="margin-top:12px"></div>' +
          '<div style="margin-top:18px"><button class="btn btn-primary" type="submit" id="pfSave">' + ic('check', 'ic-sm') + ' Simpan profil</button></div></form></section>' +
        '<section class="card card-lg reveal" aria-labelledby="pwEdit"><h2 id="pwEdit" style="font-size:20px;margin-bottom:16px">Ganti kata sandi</h2>' +
          '<form id="pwForm" novalidate><div class="form-grid" style="gap:14px;grid-template-columns:1fr">' +
            '<div class="fg"><label class="lbl" for="pwOld">Kata sandi saat ini</label><input class="field" id="pwOld" type="password" autocomplete="current-password" required></div>' +
            '<div class="fg"><label class="lbl" for="pwNew">Kata sandi baru</label><input class="field" id="pwNew" type="password" autocomplete="new-password" minlength="8" required><span class="hint">Minimal 8 karakter, memuat huruf dan angka.</span></div>' +
            '<div class="fg"><label class="lbl" for="pwNew2">Ulangi kata sandi baru</label><input class="field" id="pwNew2" type="password" autocomplete="new-password" required></div>' +
          '</div><div class="err-text" id="pwErr" role="alert" style="margin-top:12px"></div>' +
          '<div style="margin-top:18px"><button class="btn btn-soft" type="submit" id="pwSave">' + ic('key', 'ic-sm') + ' Perbarui kata sandi</button></div></form></section>' +
      '</div>'
    );
    $('#pfForm').addEventListener('submit', function (ev) {
      ev.preventDefault();
      var err = $('#pfErr');
      var payload = { name: $('#pfName').value.trim(), username: $('#pfUser').value.trim(), avatarURL: $('#pfAvatar').value.trim(), bio: $('#pfBio').value.trim(), waSettings: $('#pfWa').value.trim() };
      if (payload.name.length < 2) return err.textContent = 'Nama minimal 2 karakter.';
      if (payload.avatarURL && !/^https?:\/\//i.test(payload.avatarURL)) return err.textContent = 'Tautan foto harus diawali https://';
      err.textContent = '';
      var btn = $('#pfSave');
      setBusy(btn, true);
      api('updateProfile', payload).then(function (r) {
        if (r.user) { S.user = r.user; saveSession(); }
        toast(r.__m || 'Profil diperbarui.');
        return refreshDashboard().then(function () { route(); });
      }).catch(function (e) { err.textContent = errMsg(e); setBusy(btn, false); });
    });
    $('#pwForm').addEventListener('submit', function (ev) {
      ev.preventDefault();
      var err = $('#pwErr');
      var o = $('#pwOld').value, n = $('#pwNew').value, n2 = $('#pwNew2').value;
      if (!o) return err.textContent = 'Masukkan kata sandi saat ini.';
      if (n.length < 8 || !/[A-Za-z]/.test(n) || !/[0-9]/.test(n)) return err.textContent = 'Kata sandi baru minimal 8 karakter dan memuat huruf serta angka.';
      if (n !== n2) return err.textContent = 'Konfirmasi kata sandi tidak sama.';
      err.textContent = '';
      var btn = $('#pwSave');
      setBusy(btn, true);
      api('changePassword', { currentPassword: o, newPassword: n }).then(function (r) {
        toast(r.__m || 'Kata sandi berhasil diubah.');
        $('#pwForm').reset();
        setBusy(btn, false);
      }).catch(function (e) { err.textContent = errMsg(e); setBusy(btn, false); });
    });
  }

  /* ==========================================================================
   * HALAMAN: ADMIN (anggota, impersonasi, lifecycle, backup)
   * ========================================================================== */
  S.adminTab = 'anggota';
  function pageAdmin() {
    if (!isAdmin()) return;
    var tab = S.adminTab || 'anggota';
    var seg = '<div class="seg" role="tablist" aria-label="Bagian admin">' +
      '<button type="button" role="tab" aria-selected="' + (tab === 'anggota') + '" class="' + (tab === 'anggota' ? 'active' : '') + '" data-act="admin-tab" data-v="anggota">Anggota</button>' +
      '<button type="button" role="tab" aria-selected="' + (tab === 'operasional') + '" class="' + (tab === 'operasional' ? 'active' : '') + '" data-act="admin-tab" data-v="operasional">Operasional</button></div>';
    var head = '<div class="page-head"><div><h1>Panel Admin</h1><p>Kelola anggota, kelas, dan data aplikasi.</p></div></div><div style="margin-bottom:18px">' + seg + '</div>';
    if (tab === 'operasional') {
      setPage(head +
        '<div class="tool-grid">' +
          '<div class="tool reveal"><div class="tic">' + ic('refresh') + '</div><div><b>Evaluasi batch (lifecycle)</b><p>Luluskan peserta yang memenuhi syarat dan pindahkan batch yang sudah berakhir ke kelas alumni.</p><button class="btn btn-primary btn-sm" data-act="lifecycle">' + ic('refresh', 'ic-sm') + ' Jalankan sekarang</button></div></div>' +
          '<div class="tool reveal" style="--d:80ms"><div class="tic">' + ic('download') + '</div><div><b>Ekspor data (JSON)</b><p>Unduh seluruh tabel aplikasi. Kata sandi tidak ikut diekspor.</p><button class="btn btn-mint btn-sm" data-act="backup-export">' + ic('download', 'ic-sm') + ' Unduh backup</button></div></div>' +
          '<div class="tool reveal" style="--d:160ms"><div class="tic">' + ic('upload') + '</div><div><b>Impor data (JSON)</b><p>Pulihkan dari berkas backup. Data dengan ID yang sama akan diperbarui.</p><button class="btn btn-outline btn-sm" data-act="backup-import">' + ic('upload', 'ic-sm') + ' Pilih berkas</button></div></div>' +
          '<div class="tool reveal" style="--d:240ms"><div class="tic">' + ic('class') + '</div><div><b>Kelola kelas & tugas</b><p>Buat batch baru, generate 10 tugas, dan tinjau pengumpulan.</p><div class="row-wrap"><button class="btn btn-soft btn-sm" data-nav="kelas">Kelas</button><button class="btn btn-soft btn-sm" data-nav="tugas">Tugas</button></div></div></div>' +
        '</div>');
      return;
    }
    setPage(head +
      '<div class="toolbar"><label class="search"><span class="sr-only">Cari anggota</span>' + ic('search') + '<input class="field" id="admQ" type="search" placeholder="Cari nama, email, atau username"></label>' +
      '<button type="button" class="btn btn-primary" data-act="user-add">' + ic('plus') + ' Tambah anggota</button></div>' +
      '<div id="admList"><div class="skeleton" style="height:200px"></div></div>');
    loadAdminUsers('');
    var q = $('#admQ');
    q.addEventListener('input', debounce(function () { loadAdminUsers(q.value.trim()); }, 300));
  }

  function loadAdminUsers(query) {
    var box = $('#admList');
    if (!box) return;
    api('listUsers', { query: query }).then(function (d) {
      var users = d.users || [];
      S.dash.users = users;
      if (!users.length) { box.innerHTML = '<div class="empty">' + ic('users') + '<strong>Anggota tidak ditemukan</strong></div>'; return; }
      box.innerHTML = '<div style="display:flex;flex-direction:column;gap:10px">' + users.map(function (u, i) {
        var self = u.userId === S.user.userId;
        return '<div class="mrow reveal" style="--d:' + (i * 30) + 'ms">' + avatarHTML(u, 'sm') +
          '<div class="mi"><b>' + esc(u.name) + (self ? ' <span class="pill pill-mint">Anda</span>' : '') + '</b><span>' + esc(u.email) + ' · @' + esc(u.username) + '</span></div>' +
          '<div class="ma"><span class="pill ' + (u.role === 'Admin' ? 'pill-gold' : 'pill-gray') + '">' + esc(u.role) + '</span>' +
          '<button type="button" class="btn btn-outline btn-xs" data-act="user-progress" data-id="' + esc(u.userId) + '">' + ic('eye', 'ic-sm') + ' Progres</button>' +
          (self ? '' : '<button type="button" class="btn btn-gold btn-xs" data-act="user-imp" data-id="' + esc(u.userId) + '">' + ic('user', 'ic-sm') + ' Masuk sebagai</button>') +
          '<button type="button" class="btn btn-icon btn-sm" data-act="user-edit" data-id="' + esc(u.userId) + '" aria-label="Edit anggota">' + ic('settings', 'ic-sm') + '</button>' +
          (self ? '' : '<button type="button" class="btn btn-icon btn-sm is-danger" data-act="user-del" data-id="' + esc(u.userId) + '" aria-label="Hapus anggota">' + ic('trash', 'ic-sm') + '</button>') +
          '</div></div>';
      }).join('') + '</div>';
      hydrateIcons(box);
      observeReveals(box);
    }).catch(function (e) { box.innerHTML = '<div class="empty">' + ic('alert') + '<strong>Gagal memuat anggota</strong><span>' + esc(errMsg(e)) + '</span></div>'; });
  }

  function openUserForm(u) {
    var html = '<form id="usForm" novalidate><div class="form-grid">' +
      '<div class="fg"><label class="lbl" for="usName">Nama<span class="req">*</span></label><input class="field" id="usName" maxlength="100" value="' + esc(u ? u.name : '') + '"></div>' +
      '<div class="fg"><label class="lbl" for="usEmail">Email<span class="req">*</span></label><input class="field" id="usEmail" type="email" value="' + esc(u ? u.email : '') + '"></div>' +
      '<div class="fg"><label class="lbl" for="usUser">Username</label><input class="field" id="usUser" maxlength="40" value="' + esc(u ? u.username : '') + '"></div>' +
      '<div class="fg"><label class="lbl" for="usRole">Peran</label><select class="field" id="usRole"><option value="Member"' + (!u || u.role !== 'Admin' ? ' selected' : '') + '>Member</option><option value="Admin"' + (u && u.role === 'Admin' ? ' selected' : '') + '>Admin</option></select></div>' +
      '<div class="fg span-2"><label class="lbl" for="usBio">Bio</label><input class="field" id="usBio" maxlength="400" value="' + esc(u ? u.bio : '') + '"></div>' +
      '<div class="fg span-2"><label class="lbl" for="usPw">Kata sandi ' + (u ? '<span class="muted small">(kosongkan jika tidak diubah)</span>' : '<span class="req">*</span>') + '</label><input class="field" id="usPw" type="password" autocomplete="new-password" minlength="8"></div>' +
      '</div><div class="err-text" id="usErr" role="alert" style="margin-top:12px"></div></form>';
    var m = openModal({ title: u ? 'Edit anggota' : 'Tambah anggota', size: '', body: html,
      foot: '<button type="button" class="btn btn-outline" data-md-close>Batal</button><button type="submit" form="usForm" class="btn btn-primary" id="usSave">' + ic('check', 'ic-sm') + ' Simpan</button>' });
    var f = m.body.querySelector('#usForm');
    f.addEventListener('submit', function (ev) {
      ev.preventDefault();
      var err = m.body.querySelector('#usErr');
      var payload = { name: f.querySelector('#usName').value.trim(), email: f.querySelector('#usEmail').value.trim(), username: f.querySelector('#usUser').value.trim(), role: f.querySelector('#usRole').value, bio: f.querySelector('#usBio').value.trim(), password: f.querySelector('#usPw').value };
      if (payload.name.length < 2) return err.textContent = 'Nama wajib diisi.';
      if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(payload.email)) return err.textContent = 'Format email belum benar.';
      if (!u && payload.password.length < 8) return err.textContent = 'Kata sandi awal minimal 8 karakter.';
      if (payload.password && (payload.password.length < 8 || !/[A-Za-z]/.test(payload.password) || !/[0-9]/.test(payload.password))) return err.textContent = 'Kata sandi minimal 8 karakter dan memuat huruf serta angka.';
      if (!payload.password) delete payload.password;
      if (u) payload.userId = u.userId;
      err.textContent = '';
      var btn = m.el.querySelector('#usSave');
      setBusy(btn, true);
      api('saveUser', payload).then(function (d) {
        m.close();
        toast(d.__m || 'Data anggota tersimpan.');
        loadAdminUsers((($('#admQ') || {}).value || '').trim());
      }).catch(function (e) { err.textContent = errMsg(e); setBusy(btn, false); });
    });
  }

  function deleteUser(id) {
    var u = findUser(id) || {};
    confirmDialog('Hapus anggota?', 'Akun "' + (u.name || '') + '" beserta riwayat bacanya akan dihapus permanen.', 'Ya, hapus', true).then(function (ok) {
      if (!ok) return;
      api('deleteUser', { userId: id }).then(function (d) {
        toast(d.__m || 'Anggota dihapus.');
        loadAdminUsers((($('#admQ') || {}).value || '').trim());
      }).catch(function (e) { toast(errMsg(e), 'error'); });
    });
  }

  function openMemberProgress(id) {
    var m = openModal({ title: 'Progres anggota', size: 'lg', body: '<div class="skeleton" style="height:200px"></div>', foot: '' });
    api('getMemberProgress', { userId: id }).then(function (d) {
      var t = d.totals || {};
      var logs = (d.logs || []).slice(0, 10).map(function (l) {
        return '<div class="mrow"><div class="mi"><b>' + esc(l.bookTitle) + '</b><span>' + fmtDate(l.date) + ' · hal ' + fmt(l.startPage) + '–' + fmt(l.endPage) + '</span></div><span class="pill">' + fmtDur(l.effectiveMinutes) + '</span></div>';
      }).join('');
      var classes = (d.classes || []).map(function (c) { return '<span class="pill ' + (c.graduationStatus === 'Graduated' ? 'pill-ok' : 'pill-gray') + '">' + esc(c.className) + ' · ' + (c.graduationStatus === 'Graduated' ? 'Lulus' : 'Berjalan') + '</span>'; }).join(' ');
      m.body.innerHTML =
        '<div class="profile-hero" style="margin-bottom:16px">' + avatarHTML(d.user, 'lg') + '<div><h2>' + esc(d.user.name) + '</h2><span class="muted">' + esc(d.user.email) + '</span></div></div>' +
        '<div class="kpi-grid" style="margin-bottom:18px">' +
          '<div class="kpi-card"><span class="k-lbl">Halaman</span><span class="kpi">' + fmt(t.pages) + '</span></div>' +
          '<div class="kpi-card mint"><span class="k-lbl">Menit efektif</span><span class="kpi">' + fmt(t.minutes) + '</span></div>' +
          '<div class="kpi-card pink"><span class="k-lbl">Sesi</span><span class="kpi">' + fmt(t.sessions) + '</span></div>' +
          '<div class="kpi-card gold"><span class="k-lbl">Buku selesai</span><span class="kpi">' + fmt(t.booksFinished) + '</span></div></div>' +
        (classes ? '<div class="row-wrap" style="margin-bottom:18px">' + classes + '</div>' : '') +
        '<h3 style="font-size:18px;margin-bottom:10px">Catatan terbaru</h3>' +
        (logs ? '<div style="display:flex;flex-direction:column;gap:8px">' + logs + '</div>' : '<p class="muted">Belum ada catatan.</p>');
    }).catch(function (e) { m.body.innerHTML = '<p class="err-text">' + esc(errMsg(e)) + '</p>'; });
  }

  function impersonate(id) {
    var u = findUser(id) || {};
    confirmDialog('Masuk sebagai ' + (u.name || 'anggota') + '?', 'Anda akan melihat aplikasi seperti anggota tersebut. Gunakan tombol kembali untuk kembali ke akun admin.', 'Masuk sebagai', false).then(function (ok) {
      if (!ok) return;
      api('impersonateUser', { userId: id }).then(function (d) {
        var backup = { token: S.token, user: S.user };
        S.token = d.token;
        S.user = d.user;
        S.adminBackup = backup;
        S.dash = null;
        saveSession();
        toast(d.__m || 'Mode penyamaran aktif.', 'info');
        S.appBuilt = false;
        $('#appView').innerHTML = '';
        $('#appView').removeEventListener('click', onAppClick);
        go('#/home');
        route();
      }).catch(function (e) { toast(errMsg(e), 'error'); });
    });
  }

  function exitImpersonation() {
    if (!S.adminBackup) return;
    S.token = S.adminBackup.token;
    S.user = S.adminBackup.user;
    S.adminBackup = null;
    S.dash = null;
    saveSession();
    toast('Kembali ke akun admin.');
    S.appBuilt = false;
    $('#appView').innerHTML = '';
    $('#appView').removeEventListener('click', onAppClick);
    refreshDashboard().then(function () { go('#/admin'); route(); }).catch(function (e) { toast(errMsg(e), 'error'); });
  }

  function runLifecycle(btn) {
    confirmDialog('Jalankan evaluasi batch?', 'Peserta yang memenuhi syarat akan diluluskan dan batch yang sudah berakhir dipindah ke kelas alumni.', 'Jalankan', false).then(function (ok) {
      if (!ok) return;
      setBusy(btn, true);
      api('runLifecycle', {}).then(function (d) {
        toast(d.__m || 'Evaluasi selesai.');
        setBusy(btn, false);
        return refreshDashboard();
      }).catch(function (e) { toast(errMsg(e), 'error'); setBusy(btn, false); });
    });
  }

  function exportBackup(btn) {
    setBusy(btn, true);
    api('exportAllData', {}).then(function (d) {
      var blob = new Blob([JSON.stringify({ exportedAt: d.exportedAt, version: d.version, tables: d.tables }, null, 2)], { type: 'application/json' });
      var a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = 'kelas-membaca-backup-' + todayKey() + '.json';
      document.body.appendChild(a); a.click(); a.remove();
      setTimeout(function () { URL.revokeObjectURL(a.href); }, 2000);
      toast(d.__m || 'Backup diunduh.');
      setBusy(btn, false);
    }).catch(function (e) { toast(errMsg(e), 'error'); setBusy(btn, false); });
  }

  function importBackupFile(file) {
    var reader = new FileReader();
    reader.onload = function () {
      var json;
      try { json = JSON.parse(reader.result); } catch (e) { toast('Berkas JSON tidak valid.', 'error'); return; }
      var tables = json && json.tables;
      if (!tables || typeof tables !== 'object') { toast('Berkas ini bukan backup Kelas Membaca.', 'error'); return; }
      var names = Object.keys(tables);
      confirmDialog('Impor data?', 'Berkas berisi ' + names.length + ' tabel. Baris dengan ID yang sama akan diperbarui. Lanjutkan?', 'Impor sekarang', true).then(function (ok) {
        if (!ok) return;
        api('importAllData', { tables: tables }).then(function (d) {
          toast(d.__m || 'Impor selesai.');
          S.dash = null;
          route();
        }).catch(function (e) { toast(errMsg(e), 'error'); });
      });
    };
    reader.onerror = function () { toast('Berkas tidak dapat dibaca.', 'error'); };
    reader.readAsText(file);
  }

  /* ==========================================================================
   * BOOT — penerapan sesi, event global, dan animasi awal
   * ========================================================================== */
  function bindGlobal() {
    document.addEventListener('click', function (ev) {
      var t = ev.target.closest && ev.target.closest('[data-open-login],[data-open-register],[data-open-reset],[data-nav-go]');
      if (!t) return;
      if (t.hasAttribute('data-open-login')) { ev.preventDefault(); openLogin(); }
      else if (t.hasAttribute('data-open-register')) { ev.preventDefault(); openRegister(); }
      else if (t.hasAttribute('data-open-reset')) { ev.preventDefault(); openReset(); }
      else if (t.hasAttribute('data-nav-go')) { ev.preventDefault(); go(t.getAttribute('data-nav-go')); }
    });
    document.addEventListener('keydown', function (ev) {
      if (ev.key === 'Escape') {
        if (S.modals.length) { ev.preventDefault(); closeTopModal(); }
        else if (S.timer && $('#timerRoot .timer-overlay')) { minimizeTimer(); }
        return;
      }
      if ((ev.key === 'Enter' || ev.key === ' ') && ev.target && ev.target.getAttribute && ev.target.getAttribute('role') === 'button' && ev.target.tagName !== 'BUTTON') {
        ev.preventDefault();
        ev.target.click();
      }
    });
    document.addEventListener('submit', function (ev) {
      if (ev.target && ev.target.id === 'quickLogin') {
        ev.preventDefault();
        var f = ev.target;
        var idv = f.querySelector("[name=identifier]").value.trim(), pw = f.querySelector("[name=password]").value;
        if (!idv || !pw) { toast('Isi email/username dan kata sandi.', 'error'); return; }
        var btn = $('#qlSubmit');
        setBusy(btn, true);
        doLogin(idv, pw).catch(function (e) { toast(errMsg(e), 'error'); }).then(function () { setBusy(btn, false); });
      }
    });
    var ip = document.getElementById('importPicker');
    if (ip) ip.addEventListener('change', function () { if (ip.files && ip.files[0]) importBackupFile(ip.files[0]); ip.value = ''; });
    window.addEventListener('hashchange', function () {
      if (!S.token) { route(); return; }
      route();
    });
    window.addEventListener('beforeunload', function () { if (S.timer) saveTimerState(); });
    document.addEventListener('visibilitychange', function () { if (document.hidden && S.timer) saveTimerState(); });
  }

  function boot() {
    document.documentElement.classList.add('js');
    hydrateIcons($('#bw-app-root'));
    bindGlobal();
    buildLanding();
    initLandingMotion();
    if (!apiReady()) {
      toast('URL API belum diatur. Edit CFG.API_URL pada tema.', 'error');
    }
    var sess = loadSession();
    if (sess && sess.token && sess.user) {
      S.token = sess.token; S.user = sess.user; S.adminBackup = sess.admin || null;
      restoreTimerIfAny();
      refreshDashboard().then(function () {
        if (!parseHash()) location.hash = '#/home';
        route();
      }).catch(function (e) {
        if (!AUTH_CODES.some(function (c) { return e && e.code === c; })) {
          toast('Belum dapat terhubung ke server. ' + errMsg(e), 'error');
        }
        if (!S.token) { route(); return; }
        route();
      });
    } else {
      route();
    }
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', boot);
  else boot();


})();

